// DE LEESWAARHEID: bronnen ophalen, parsen en tot één weergavemodel bouwen.
//
// Alles wat de kijkstand toont hangt aan `model()`. De store is bewust dun: hij
// orkestreert (ophalen -> worker -> model) en houdt de laadtoestand bij; het
// denkwerk zit in de framework-vrije modellaag (src/model/).
//
// De modelbouw loopt ALTIJD via de module-worker (loadSourcesInWorker). Dat is
// een bewuste afwijking van de oude viewer, die met useWorkerFor() onder de
// 1,5 MB synchroon bleef: die drempel bestaat om workeroverhead te vermijden,
// maar hij maakt het worker-pad óók onzichtbaar voor kleine corpora — en juist
// dat pad is het bundelgevoeligste stuk van de migratie (de dt4-poort
// tools/worker-smoke.mjs bewaakt het). Draait de worker niet (geen Worker in
// de omgeving, of hij faalt), dan valt de store synchroon terug, precies zoals
// de oude ingest dat deed; `motor()` zegt welk pad het werd.
import { createSignal } from 'solid-js';
import {
  addSource, buildModel, buildNav, collectionLevelQuery, containerListQuery,
  containerSkeletonTurtle, coveredCountQuery,
  createStore, decomposedIndexRows, detectFormat, detectSource, excludeGraphsFor,
  formShapesQuery, geraaktePolicies, graphForSource,
  hasOwnLabel, hydrateInto, isEndpointTimeout,
  listSkeletonTurtle, loadSources, loadSourcesInWorker,
  nodeFormQuery, nodeLabelsQuery,
  policyDetailQuery, policyListFirstQuery, policyListQuery,
  scopeNavToPolicy, scopeNavToSet,
  sparqlConstruct, sparqlSelect, t,
} from '../model-grens.js';
import type {
  Binding, Bron, Delta, Fout, Graaf, Model, ModelResultaat, Nav,
} from '../model-grens.js';
import { EXAMPLES_BASE, VOCABULAIRE, vocabulaireNaam } from '../model/default-corpus.js';
import { ARTIFACT_FORM_SHAPE_TTL } from '../model/artifact-form-shape.js';
import { builtinShapes, coveredClasses, coveredNodes, readShapes } from '../model/forms.js';
import { getLang } from '../model/i18n.js';

export type LaadStatus = 'leeg' | 'laden' | 'klaar' | 'fout';
export type Motor = 'worker' | 'hoofddraad';
/** 'eerste' = het eerste beeld van de tweefasige endpoint-lading staat er, de
 *  volledige index is nog onderweg. Zie laadPolicyLijst. */
export type LijstFase = 'eerste' | null;
/** Welke slag van de endpointlading faalde: de eerste (er staat niets) of de
 *  volledige index (het eerste beeld blijft staan). Bepaalt beide meldingen. */
export type LijstFout = 'endpoint' | 'volledigeIndex' | null;
export type { Bron };
export type CorpusFout = Fout;
export type CorpusModel = Model;

const [model, setModel] = createSignal<CorpusModel | null>(null);
const [laadStatus, setLaadStatus] = createSignal<LaadStatus>('leeg');
const [fouten, setFouten] = createSignal<CorpusFout[]>([]);
const [bronnen, setBronnen] = createSignal<Bron[]>([]);
const [quadCount, setQuadCount] = createSignal(0);
const [motor, setMotor] = createSignal<Motor | null>(null);
const [nav, setNav] = createSignal<Nav>(null);
const [scopedNav, setScopedNav] = createSignal<Nav>(null);
// BEVINDING I-6. Een `?policy=`/`?set=` die in de geladen bronnen niets
// aanwijst is geen fout maar wél iets om te MELDEN: de pagina snoeit dan niets
// en zou anders het volledige corpus tonen alsof de deeplink werkte. `null` =
// er was geen scope, of hij loste op. De statusregel leest dit signaal en zet
// er `status.policyNotFound`/`status.setNotFound` achter — precies de
// `scopeNote` van applyScopeAndRender (doc.js r.1226-1240).
const [scopeNietGevonden, setScopeNietGevonden] = createSignal<'policy' | 'set' | null>(null);
// De GRAAF als signaal: de kaarten lezen hem rechtstreeks (terugverwijzingen,
// ledenniveaus) en moeten dus meebewegen. `graafVersie` telt de bijmengingen
// die de graaf IN PLAATS mutaties geven: de identiteit van de store verandert
// dan niet, dus een teller is het signaal.
const [graaf, setGraaf] = createSignal<Graaf | null>(null);
const [graafVersie, setGraafVersie] = createSignal(0);
const [endpoint, setEndpoint] = createSignal<string | null>(null);
// IS HET ENDPOINT EEN BRON van deze lading? De endpoint-CHROME (fase-skelet,
// `data-lijstfase`, de endpoint-foutmelding met URL en CORS-hint) hangt hieraan.
// Niet af te leiden uit `bronnen()`: die is aan het begin van een lading nog
// leeg, en dan zou de chrome bij elke bestandslading even aanflitsen.
//
// DE GEMENGDE STAND STAAT SINDS 14 SEP 2026 AAN DEZE KANT (zie `laadBestanden`).
// Hier stond: "in het gemengde geval is het bestand de bron en blijft de gewone
// documentweergave staan" — het endpoint was daar geen bron maar een
// detail-verrijker, en dus stond er geen endpoint-chrome. Sinds de unie is élke
// ?src= een volwaardige bron: staat er een endpoint in de lijst, dan is het
// endpoint óók bron en hoort zijn chrome erbij. `false` betekent nu precies één
// ding: er is geen endpoint in deze lading.
const [endpointIsBron, setEndpointIsBron] = createSignal(false);
const [lijstFase, setLijstFase] = createSignal<LijstFase>(null);
const [compatIndex, setCompatIndex] = createSignal(false);
// WELKE fout de lijstlading trof. Niet af te leiden uit "staat er toevallig nog
// een model": `laadCorpus` maakt het model niet leeg bij het starten van een
// nieuwe lading, dus wie van een bestandscorpus naar een falend endpoint
// wisselt zou anders de fase-2-melding krijgen voor een fase-0-fout.
const [lijstFout, setLijstFout] = createSignal<LijstFout>(null);
// De i18n-sleutel van de melding die bij DEZE lading hoort. De bevroren viewer
// zet er drie: 'load.sources' (bestanden), 'load.source' (één scope-IRI) en
// 'load.queryEndpointAt' (endpoint) — doc.js r.11684, r.11726 en r.11251.
const [laadMelding, setLaadMelding] = createSignal<string>('load.sources');
// DE TELLING "N gespecificeerd(e) object(en)" IN ENDPOINTMODUS. In
// bestandsmodus telt de weergave zelf, over de clientgraaf (`countCovered`);
// in endpointmodus staat het corpus daar niet in en zou diezelfde telling
// zeggen hoeveel de lezer toevallig al opengeklapt heeft. `null` = geen
// endpointtelling, dan telt de weergave zoals altijd.
const [gedektTelling, setGedektTelling] = createSignal<number | null>(null);

export {
  bronnen, compatIndex, endpoint, endpointIsBron, fouten, gedektTelling, graaf, graafVersie,
  laadMelding,
  laadStatus, lijstFase, lijstFout, model, motor, nav, quadCount, scopedNav,
  scopeNietGevonden,
};

// Een oplopend volgnummer laat een verouderde lading (er kwam intussen een
// nieuwe laadCorpus-aanroep) stilletjes vervallen — zelfde ingestSeq-truc als
// in de oude viewer.
let volgnummer = 0;

// De GRAAF van de laatste lading staat hierboven als signaal. Hij is er zodat
// een taalwissel (of een scope-wissel) alleen het MODEL hoeft te herbouwen —
// precies wat switchLang in de oude viewer doet met state.store — én zodat de
// kaarten losse knopen uit de graaf kunnen lezen. Op het worker-pad komt hij ná het
// model binnen (graaf-overdracht), dus `graafGereed` zegt wanneer hij bruikbaar
// is; faalt de overdracht, dan blijft hij null en is herbouwen simpelweg niet
// mogelijk (zoals in de oude viewer).
let graafGereed: Promise<void> = Promise.resolve();
let laatsteSetScope: string | null = null;
let laatstePolicyScope: string | null = null;
let laatsteExcludeGraphs: string[] = [];
// De ONBEWERKTE ?exclude-graph=-waarden van deze lading. Nodig omdat de
// per-endpoint-config (excludeGraphsFor) pas kan rekenen als het endpoint
// bekend is — en dat kan bij een gedetecteerde ?src= pas ná de detectie.
let laatsteRuweExclude: string[] | undefined;

// --- DE UNIE: de BESTANDSHELFT van deze lading ------------------------------
// In de gemengde stand (endpoint én bestanden in dezelfde ?src=-lijst) bouwt
// élke endpointfase de graaf vanaf nul uit de bronnenlijst die zij meegeeft.
// Zou zij alleen haar eigen skelet meegeven, dan veegde fase 1 de bestanden weg
// en fase 2 nog een keer. Daarom staan de opgehaalde bestandsbronnen hier: elke
// verwerkBronnen-aanroep van de endpointkant zet ze er weer vóór.
//
// In de ZUIVERE endpointstand is deze lijst leeg, en dan is `[...basisBronnen,
// skelet]` letterlijk `[skelet]` — de bestaande stand verandert per constructie
// niet. Hun FOUTEN staan er om dezelfde reden naast: `verwerkBronnen` vervangt
// `fouten()` bij elke aanroep, dus zonder deze lijst zou de fasewissel een
// mislukte ?src= stilletjes uit de melding poetsen.
let basisBronnen: Bron[] = [];
let basisFouten: CorpusFout[] = [];

const metBasis = (bron: Bron[]): Bron[] => (basisBronnen.length
  ? [...basisBronnen, ...bron] : bron);
const metBasisFouten = (extra: CorpusFout[]): CorpusFout[] => (basisFouten.length
  ? [...basisFouten, ...extra] : extra);

/** Noteer het endpoint van deze lading (en wat daaraan hangt). Wordt twee keer
 *  aangeroepen: synchroon voor ?sparql=, en later voor een ?src= die een
 *  endpoint bleek. */
function noteerEndpoint(ep: string | null): void {
  setEndpoint(ep);
  laatsteExcludeGraphs = excludeGraphsFor(ep, laatsteRuweExclude);
}

/** Eén te laden bron: waar hij vandaan komt en hoe hij in de bronnenlijst
 *  heet. Voor ?src= is dat hetzelfde (de URL ís de naam, zoals in de oude
 *  ingest); het voorbeeldcorpus houdt zijn korte bestandsnaam.
 *
 *  `detecteer` zegt of deze URL nog een SOORT moet krijgen. Alleen ?src= is
 *  generiek (bestand of endpoint); ?ttl= en het voorbeeldcorpus zijn per
 *  definitie bestanden en gaan zonder detectie hun vaste weg — precies de
 *  tweedeling van het boot-blok in de bevroren viewer (partitionSources over
 *  `srcParams`, de legacy-aliassen eromheen). */
interface TeLaden {
  name: string;
  url: string;
  detecteer?: boolean;
  /** STIL FALEN. Een ondersteunende bron (vocabulaire, labels) is niet gevraagd:
   *  de app laadt hem uit zichzelf mee. Komt hij niet door — een uitrol die de
   *  bestanden ergens anders heeft staan, een offline pagina — dan hoort dat
   *  geen foutregel in het bronnenpaneel op te leveren bij een lezer die er
   *  nooit om vroeg. De labels vallen dan terug op de kale IRI's, en dat is
   *  precies wat er zonder deze bronnen ook zou gebeuren. */
  stil?: boolean;
}

/** De bestandsbronnen van deze lading.
 *
 *  DE DEMO-TAK IS VERVALLEN — EIGENAARSBESLUIT 9 SEP 2026, letterlijk: "echt
 *  leeg natuurlijk. demobronnen moeten eruit". Hier stond
 *  `return DEFAULT_EXAMPLES.map(...)`: zonder parameters laadde de app het
 *  voorbeeldcorpus, precies zoals de bevroren viewer (`else
 *  { loadFromExamples(); }`), en dat was zelfs als regressie geledgerd (I5b) toen
 *  een tussenversie leeg bleef. Dat ledger is hiermee OMGEKEERD, op verzoek van
 *  de eigenaar: wie de app opent hoort zijn eigen lege werkblad te zien, niet
 *  het beleid van een fictieve gemeente dat hij eerst moet wegklikken. De
 *  demobestanden blijven bestaan en blijven bereikbaar — via `?src=`, via de
 *  links op index.html, en via het voorbeeldlinkje in de lege staat van het
 *  bronnenpaneel.
 *
 *  WAT WÉL AUTOMATISCH MEEKOMT is de VOCABULAIRE (`VOCABULAIRE` in
 *  default-corpus.js: het profielvocabulaire en het TOOI-labelfragment). Zonder
 *  die twee toont een willekeurige eigen bron kale IRI's in plaats van woorden —
 *  ze horen bij de VIEWER, niet bij de demo. Ze komen er alleen bij als er iets
 *  te labelen is: zonder eigen bron blijft de lading leeg, en bij een endpoint
 *  of een scope-IRI komen de labels uit die bron zelf (dezelfde volgorde als het
 *  boot-blok van de bevroren viewer: bronnen, dan `?sparql=`, dan
 *  `?policy=`/`?set=`).
 *
 *  De lijst en het pad komen uit dezelfde gedeelde plek als in de oude viewer
 *  (src/model/default-corpus.js), zodat een andere uitrol hem daar omzet zonder
 *  code te raken. */
export function teLadenBronnen(
  p: { src: string[]; ttl?: string[]; sparql?: string | null; scope?: string | null },
): TeLaden[] {
  // ?src= eerst, dan de legacy ?ttl= — de volgorde van het boot-blok (eerst
  // `partitionSources(srcParams)`, dan de legacyTtl-lus die erachteraan duwt).
  const alles: TeLaden[] = [
    ...p.src.map((url) => ({ name: url, url, detecteer: true })),
    ...(p.ttl || []).map((url) => ({ name: url, url })),
  ];
  // ONTDUBBELEN OP URL, eerste wint (dt3-fixronde, review I-1). Dezelfde URL
  // twee keer in `?src=` (of één keer in `?src=` en één keer in `?ttl=`) leverde
  // twee bronnen op die volgens `graphForSource` DEZELFDE named graph dragen:
  // hun triples vallen op één hoop, ze delen één lokale kopie en één
  // index-entry, en de bronnenbalk toonde twee bewerkbronnen tegelijk terwijl er
  // per spec precies één mag zijn. De tweede lading voegt bovendien niets toe —
  // de graaf ontdubbelt identieke quads zelf — dus hij kost alleen een fetch.
  const gezien = new Set<string>();
  const uit = alles.filter((t) => !gezien.has(t.url) && !!gezien.add(t.url));
  // Niets gevraagd (of alleen een endpoint/scope-IRI): dan is er ook niets te
  // labelen, en blijft de lijst leeg.
  if (!uit.length) return [];
  // De vocabulaire erachteraan, maar alleen wat er nog niet bij zit: dezelfde
  // vocabulaire kan al expliciet in `?src=` staan (de links op index.html doen
  // dat), en dan zou ze onder twee verschillende URL's twee named graphs krijgen
  // — precies de dubbelloading die de ontdubbeling hierboven weghoudt.
  const alVocab = new Set(uit.map((t) => vocabulaireNaam(t.url)).filter(Boolean));
  return [
    ...uit,
    ...VOCABULAIRE.filter((n: string) => !alVocab.has(n))
      .map((name: string) => ({ name, url: EXAMPLES_BASE + name, stil: true })),
  ];
}

interface Gehaald { bronnen: Bron[]; fouten: CorpusFout[]; endpoints: string[] }

async function haalBronnen(lijst: TeLaden[]): Promise<Gehaald> {
  const uit: Bron[] = [];
  const fout: CorpusFout[] = [];
  const eps: string[] = [];
  const resultaten = await Promise.all(lijst.map(async ({ name, url, detecteer, stil }) => {
    // De GENERIEKE ingang (?src=): eerst uitzoeken WAT dit is. detectSource
    // levert een bestand mét inhoud terug, dus dit vervangt de GET hieronder —
    // het haalt hem niet nog een keer op.
    if (detecteer) {
      const r = await detectSource(url);
      if (r.kind === 'sparql') return { endpoint: r.url };
      if (r.kind === 'data') {
        return { bron: { name, url, content: r.content, format: r.format } };
      }
      return stil ? {} : { fout: { url, message: r.message } };
    }
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const content = await r.text();
      return { bron: { name, url, content, format: detectFormat(url, content) as string } };
    } catch (e) {
      if (stil) return {};
      return { fout: { url, message: e instanceof Error ? e.message : String(e) } };
    }
  }));
  // Volgorde behouden: ?src=-parameters zijn geordend (bronvolgorde telt in het
  // model), dus de resultaten worden op parametervolgorde teruggelegd.
  for (const r of resultaten) {
    if (r.bron) uit.push(r.bron);
    else if (r.endpoint) eps.push(r.endpoint);
    else if (r.fout) fout.push(r.fout);
  }
  return { bronnen: uit, fouten: fout, endpoints: eps };
}

// Modelbouw met behoud van de graaf. De worker stuurt eerst het model en
// daarna de graaf; die tweede boodschap wordt hier op de hoofddraad in een
// eigen store gehydrateerd (in stukjes, zodat de UI responsief blijft), precies
// als ingestViaWorker in de oude viewer.
async function bouwModel(bron: Bron[], opties: { setScope: string | null; lang: string }):
Promise<{ bericht: ModelResultaat; motor: Motor }> {
  try {
    const store = createStore();
    let klaarmelden: () => void = () => {};
    graafGereed = new Promise<void>((r) => { klaarmelden = r; });
    const bericht = await loadSourcesInWorker(bron, {
      setScope: opties.setScope,
      lang: opties.lang,
      onStore: (lading) => {
        // lading null = de overdracht faalde: verder zonder graaf (de weergave
        // staat er al; alleen herbouwen kan dan niet).
        if (!lading) { klaarmelden(); return; }
        void hydrateInto(store, lading).then(() => {
          setGraaf(() => store);
          setGraafVersie((v) => v + 1);
          klaarmelden();
        });
      },
    });
    return { bericht, motor: 'worker' };
  } catch {
    // Geen Worker (node/jsdom) of een worker die niet startte: synchroon door.
    // Het model is identiek; alleen de hoofddraad staat even stil — en de graaf
    // is er meteen, want loadSources geeft hem gewoon terug.
    const bericht = loadSources(bron);
    setGraaf(() => bericht.store ?? null);
    setGraafVersie((v) => v + 1);
    graafGereed = Promise.resolve();
    return { bericht, motor: 'hoofddraad' };
  }
}

// De scoping van de nav. TWEE SOORTEN, en ze sluiten elkaar uit (de
// weergavestore zorgt daarvoor: ?policy= wist ?set= en omgekeerd):
//
//  - ?set=    — de WORKER doet hem zelf (model-worker.js: scopeNavToSet met de
//               graaf die hij toch al heeft) en levert dan `null` óf een
//               gescopete nav; op het synchrone terugvalpad levert loadSources
//               hem NIET (undefined) en rekent de hoofddraad hem hier uit. Dat
//               is precies de tweedeling van applyScopeAndRender in de bevroren
//               viewer (doc.js r.1231-1239): `scopedNavFromWorker !== undefined`
//               telt, anders zelf rekenen.
//  - ?policy= — snoeit tot het PAD naar die policy (scopeNavToPolicy). De
//               worker kent deze scoping niet: hij krijgt alleen setScope mee.
//               Zijn `scopedNav` is dus geen uitspraak over ?policy=, en de
//               hoofddraad rekent hem ALTIJD zelf uit. Zonder dat onderscheid
//               wint de null van de worker en blijft de boom ongesnoeid.
function eigenScoping(navBoom: Nav, scope: Scope): Nav {
  if (!navBoom) return null;
  if (scope.policy) return scopeNavToPolicy(navBoom, scope.policy)?.nav ?? null;
  const g = graaf();
  if (!scope.set || !g) return null;
  return scopeNavToSet(navBoom, g, scope.set)?.nav ?? null;
}

/** De actieve scoping van deze lading. Hooguit één van de twee is gevuld. */
interface Scope { set: string | null; policy: string | null }

const huidigeScope = (): Scope => ({ set: laatsteSetScope, policy: laatstePolicyScope });

/** Herbouw het MODEL uit de bewaarde graaf — geen fetch, geen her-parse.
 *  Dit is switchLang uit de oude viewer: `setLang` (doet de aanroeper, via de
 *  weergavestore) en dan `state.model = buildModel(state.store)`. Ook de
 *  ?set=-scoping loopt hierlangs, zodat een scope-wissel straks hetzelfde
 *  goedkope pad heeft (rescope in de oude viewer). */
export async function herbouw(
  opties: { lang?: string; setScope?: string | null; policyScope?: string | null } = {},
): Promise<void> {
  const seq = volgnummer;
  if (!model()) return;                       // niets geladen: niets te hertalen
  if (opties.setScope !== undefined) laatsteSetScope = opties.setScope;
  if (opties.policyScope !== undefined) laatstePolicyScope = opties.policyScope;
  // Op het worker-pad kan de graaf nog onderweg zijn; wachten is wat de oude
  // viewer ook doet (setStatus(t('load.graph')) + await state.storeReady).
  await graafGereed;
  if (seq !== volgnummer) return;             // er kwam intussen een nieuwe lading
  const g = graaf();
  if (!g) return;                             // graaf-overdracht faalde
  const m = buildModel(g);
  const n = buildNav(m);
  const scope = huidigeScope();
  setModel(m);
  setNav(() => n);
  setScopedNav(() => eigenScoping(n, scope));
}

// De opties die elke lading meeneemt naar de modelbouw.
interface BouwOpties { setScope: string | null; policyScope: string | null; lang: string }

// --- Bijgeladen materiaal: naast de bronnenlijst, niet erin ------------------
// De collectieniveaus van een ledenlijst en de detail-CONSTRUCTs van de kaarten
// zijn GEEN bronnen van het corpus: de lezer heeft ze niet aangewezen, ze hebben
// geen eigen adres, en ze horen dus niet in de bronnenlijst of in de telling van
// de statusregel. (Ze deden dat wel, en dat maakte die telling van
// gebruikersgedrag afhankelijk: "2 bron(nen), 33.092 triples" tegen "1 bron(nen),
// 31.851" in de bevroren viewer, afhankelijk van wat je vóór of ná de
// fasewissel had opengeklapt — bevinding I-3. Een kaart die je uitklapt haalt
// zijn regels op en mag de bronnentelling niet verzetten.)
//
// Ze moeten wél een her-ingest overleven: fase 2 bouwt de graaf vanaf nul.
// Daarom staan ze in deze aparte lijst, die `setBronnen` nooit vervangt, en
// worden ze na ELKE modelbouw opnieuw in de verse graaf gemengd. Dat sluit
// meteen het racevenster van bevinding M-4: materiaal dat binnenkomt terwijl de
// modelbouw loopt, kan niet meer uit een lijst worden weggevaagd — het wordt
// hooguit twee keer gemengd, en de graaf ontdubbelt identieke quads zelf.
// TWEE bijlaadpaden vullen deze lijst: het collectieniveau van een ledenlijst
// (haalCollectieNiveau) en het detail van één kaart (haalDetail). Ze gelden
// geen van beide als BRON en volgen daarom dezelfde weg; één mechanisme, zodat
// de statusregel-telling en het overleven van een her-ingest niet per pad
// verschillen. Een DERDE pad — de knoop-CONSTRUCT van de verkenner — hoorde er
// tot 16 sep 2026 bij en verdween met de verkenner.
// CONTRACTWIJZIGING (dt3, lane-bronnen-edit): dit was een gewone `let` en is nu
// een SIGNAAL. Reden: de bronnenbalk moet dit materiaal kunnen MELDEN (zie
// `bijgeladenKnopen` onderaan) en een melding die niet meebeweegt met wat de
// een uitgeklapte kaart erbij haalt, liegt bij de tweede klik. De lijst zelf,
// zijn vulling en zijn bijlaadpaden blijven ongewijzigd.
const [bijgeladen, setBijgeladen] = createSignal<{ iri: string; ttl: string; ep: string }[]>([]);

/** Meng het bijgeladen materiaal (opnieuw) in de HUIDIGE graaf. `true` = er is
 *  iets gemengd, dus wie een MODEL uit die graaf afleidt moet het herbouwen. */
function hermengBijgeladen(): boolean {
  const g = graaf();
  if (!g || !bijgeladen().length) return false;
  for (const k of bijgeladen()) addSource(g, k.ttl, 'ttl', graphForSource({ url: k.ep }, 0));
  setGraafVersie((v) => v + 1);
  return true;
}

/** Bronnen -> model -> store. Eén tail voor ALLE laadpaden (bestanden, de
 *  scope-IRI en het endpoint), zodat een endpoint-lading precies dezelfde
 *  statusovergangen en dezelfde nav-scoping krijgt als een bestandslading. */
async function verwerkBronnen(
  seq: number, bron: Bron[], extraFouten: CorpusFout[], opties: BouwOpties,
): Promise<boolean> {
  const { bericht, motor: gebruikt } = await bouwModel(bron, opties);
  if (seq !== volgnummer) return false;
  setBronnen(bron);
  setModel(bericht.model || null);
  setNav(() => bericht.nav ?? null);
  // Heeft de worker de scoping gedaan, dan geldt zijn uitkomst — óók `null`,
  // want dat betekent "?set= wijst niets aan". Alleen als hij hem niet
  // meelevert (undefined: het synchrone pad) rekent de hoofddraad zelf.
  // ?policy= rekent de hoofddraad altijd zelf uit (de worker kent hem niet);
  // voor ?set= geldt de uitkomst van de worker zodra hij er een meelevert.
  const gescoped = (bericht.scopedNav !== undefined && !opties.policyScope)
    ? bericht.scopedNav
    : eigenScoping(bericht.nav ?? null,
      { set: opties.setScope, policy: opties.policyScope });
  setScopedNav(() => gescoped);
  // Een gevraagde scope die op `null` uitkomt WIJST NIETS AAN. Zonder scope is
  // `null` de gewone stand en valt er niets te melden.
  const gevraagd = opties.policyScope ? 'policy' : (opties.setScope ? 'set' : null);
  setScopeNietGevonden(gevraagd && !gescoped ? gevraagd : null);
  setQuadCount(bericht.quadCount || 0);
  setMotor(gebruikt);
  setFouten([...extraFouten, ...(bericht.errors || [])]);
  setLaadStatus(bericht.model ? 'klaar' : 'fout');
  // De verse graaf krijgt het al bijgeladen materiaal terug. Na de tellingen,
  // zodat die precies de BRONNEN beschrijven en niet wat een uitgeklapte kaart
  // erbij haalde.
  await graafGereed;
  if (seq !== volgnummer) return !!bericht.model;
  // Het MODEL moet mee. Een bijgeladen kaartdetail draagt REGELS: zonder deze
  // herbouw staat een kaart
  // die de lezer tijdens fase 1 uitklapte na de fasewissel weer leeg, terwijl
  // `detailGeladen` zegt dat er niets meer te halen valt. Dat is dezelfde
  // rebuild die ensureDetail in de bevroren viewer deed.
  if (hermengBijgeladen()) herbouwUitGraaf();
  return !!bericht.model;
}

function meldFout(seq: number, fout: CorpusFout): void {
  if (seq !== volgnummer) return;
  // `metBasisFouten` is in de zuivere standen de identiteit (de lijst is dan
  // leeg); in de UNIE houdt hij de meldingen van de bestandshelft in beeld.
  setFouten(metBasisFouten([fout]));
  setLaadStatus('fout');
}

// --- Pad 1: ?src=-bestanden --------------------------------------------------

async function laadBestanden(seq: number, urls: TeLaden[], opties: BouwOpties): Promise<void> {
  const gehaald = await haalBronnen(urls);
  if (seq !== volgnummer) return;
  // Bleek een ?src= een ENDPOINT, dan telt hij als endpoint van deze lading —
  // vóór een eventuele ?sparql=, want in het boot-blok komen de gedetecteerde
  // endpoints eerst in de lijst en wint `endpoints[0]` (doc.js r.11688-11699).
  if (gehaald.endpoints.length) noteerEndpoint(gehaald.endpoints[0]);
  // DE VOCABULAIRE TELT NIET MEE IN DEZE KEUZE, en dat is geen detail. Zij komt
  // sinds 9 sep 2026 automatisch achter elke bestandslading aan; zou zij als
  // "bestand" meetellen, dan zou een `?src=<endpoint>` (geen enkel eigen
  // bestand, wel een endpoint) opeens de BESTANDSroute nemen met het endpoint als
  // bijlaadbron — een andere app dan de lezer vroeg. Op de endpointroute laadt
  // de vocabulaire dus niet mee; daar komen de labels uit het endpoint zelf.
  const eigenBronnen = gehaald.bronnen.filter((b) => !vocabulaireNaam(b.url));
  const ep = endpoint();
  if (!eigenBronnen.length && ep) {
    // Geen enkel BESTAND, wel een endpoint: dan is het endpoint de enige bron —
    // dezelfde keuze als `if (dataSources.length) ingest(...) else
    // loadFromSparql()`. De detectiefouten van de andere ?src=-waarden vallen
    // daarmee weg, precies als daar.
    setLaadMelding('load.queryEndpointAt');
    setEndpointIsBron(true);
    await laadVanEndpoint(seq, ep, opties.policyScope, opties);
    return;
  }
  if (!eigenBronnen.length) {
    setBronnen([]); setModel(null); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setFouten(gehaald.fouten);
    setLaadStatus('fout');
    return;
  }
  // DE UNIE (eigenaarsoordeel 14 sep 2026). Hier hield het op: bestanden én
  // endpoint in één ?src=-lijst liep verder als een gewone BESTANDSlading, met
  // het endpoint alleen genoteerd voor de detail-CONSTRUCTs van uitgeklapte
  // kaarten. De bestanden waren daarmee het corpus en het endpoint een
  // verrijker, en de beleidssets die alleen in het endpoint staan kwamen
  // helemaal niet in beeld. De eigenaar, nadat hij daar op zijn GLO-deeplink
  // precies op stuitte: "dat is wat mij betreft niet logisch. heeft dat een
  // technische reden? Als het onontkoombaar is zou ik het eerder nog andersom
  // zien ... de SPARQL als corpus en .ttl als verrijking... dat past beter bij
  // het statischere karakter van ttl's."
  //
  // Er is geen onontkoombare technische reden, en de goede uitkomst is geen van
  // beide rangordes maar de UNIE: élke ?src= is een volwaardige bron. De
  // bestanden laden vol (hieronder), het endpoint draait daarna zijn eigen
  // tweefasige luie lading, en alles mengt in dezelfde clientgraaf.
  //
  // DE VOLGORDE IS BEWUST: eerst de bestanden RENDEREN, dan pas het endpoint.
  // Ze staan er al (opgehaald), ze laden vol, en een lezer hoort ze niet te
  // moeten afwachten op een netwerkhop die ook kan falen. Faalt die hop, dan
  // blijft deze helft staan — zie de foutafhandeling in `laadPolicyLijst`.
  if (ep) setEndpointIsBron(true);
  // BRONNENLAAG (dt3): bronnen met een lokale OPFS-kopie komen uit die kopie en
  // de werkbestanden van deze browser komen erbij — zie registreerBronVoorbewerking.
  const voor = await voorbewerkt(gehaald.bronnen);
  basisBronnen = voor.lijst;
  basisFouten = voor.fout ? [voor.fout, ...gehaald.fouten] : gehaald.fouten;
  await verwerkBronnen(seq, basisBronnen, basisFouten, opties);
  if (seq !== volgnummer || !ep) return;
  await laadVanEndpoint(seq, ep, opties.policyScope, opties);
}

// --- Pad 2 (bevinding I5a): ?policy=/?set= ZONDER bronnen --------------------
// De scope-IRI is dan zelf de bron. De bevroren viewer doet dit in het
// boot-blok (doc.js r.11724-11734): fetch, detectFormat, ingest — geen
// detectie, geen endpoint. Zonder dit pad opent een gedeelde ?policy=-deeplink
// een lege pagina, want er staat geen ?src= in.

async function laadScopeBron(seq: number, scopeIri: string, opties: BouwOpties): Promise<void> {
  try {
    const r = await fetch(scopeIri);
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const content = await r.text();
    if (seq !== volgnummer) return;
    const voor = await voorbewerkt([{
      name: scopeIri, url: scopeIri, content, format: detectFormat(scopeIri, content),
    }]);
    await verwerkBronnen(seq, voor.lijst, voor.fout ? [voor.fout] : [], opties);
  } catch (e) {
    meldFout(seq, {
      url: scopeIri,
      message: t('err.scopeFetch', {
        iri: scopeIri, msg: e instanceof Error ? e.message : String(e),
      }),
    });
  }
}

// --- Pad 3 (bevinding I5a): ?sparql=<endpoint> zonder bronnen ---------------
// Het endpoint IS dan de bron. Twee routes, precies als loadFromSparql:
//   * MET ?policy=: alleen dat ene detail (policyDetailQuery, één CONSTRUCT) —
//     de schone detailroute van een deeplink;
//   * ZONDER scope: de TWEEFASIGE lijstlading (loadPolicyList). Fase 1 haalt
//     per soort de eerste 60 titels (policyListFirstQuery, ~0,1 s) zodat er
//     meteen ECHTE kaarten staan; fase 2 haalt de volledige index parallel met
//     de containerlijst en vervangt het skelet. Faalt fase 1, dan doet fase 2
//     het werk alleen; faalt fase 2 terwijl fase 1 stond, dan blijft dat eerste
//     beeld staan met de melding erbij — beter iets dan niets.
//
// MEEVERHUISD MET DE KAARTENLIJST: het lazy bijladen van kaartdetails
// (ensureDetail/eagerOfferAgreementDetails) staat verderop in dit bestand —
// `detailNodig`, `haalDetail` en `haalKaartDetails`. Nog NIET meeverhuisd: het
// terugzetten van de gebruikersstaat over de fasewissel heen
// (captureListUi/restoreListUi). De open-stand overleeft die wissel inmiddels
// via de onthouden open-stand van de lijst; het scrollanker en de openstaande
// filterpanelen zijn vormgeving van de tweefasige lading (taak 7).

/** De volledige index, met automatische terugval. Eerst het SNELLE pad
 *  (policyListQuery); loopt dat in een servertimeout of 5xx — wat op een
 *  streaming-evaluator structureel gebeurt — dan de COMPATIBILITEITSMODUS
 *  (vijf platte queries, client-side gemergd). Faalt ook dat, dan telt de
 *  OORSPRONKELIJKE fout: die beschrijft wat er met de bedoelde query misging. */
async function indexRijen(ep: string): Promise<Binding[]> {
  try {
    return await sparqlSelect(ep, policyListQuery());
  } catch (e) {
    if (!isEndpointTimeout(e)) throw e;
    try {
      const rijen = await decomposedIndexRows(ep);
      setCompatIndex(true);
      return rijen;
    } catch { throw e; }
  }
}

async function laadPolicyLijst(seq: number, ep: string, opties: BouwOpties): Promise<void> {
  let eersteBeeld = false;
  try {
    const rijen = await sparqlSelect(ep, policyListFirstQuery());
    if (seq !== volgnummer) return;
    if (rijen.length) {
      setLijstFase('eerste');
      eersteBeeld = await verwerkBronnen(seq, metBasis([{
        name: `${ep} (eerste beeld, ${rijen.length} rijen)`,
        url: ep, content: listSkeletonTurtle(rijen), format: 'ttl', fromSparql: true,
      }]), metBasisFouten([]), opties);
      // De lading is nog niet klaar: de statuslijn hoort dat te weten.
      if (eersteBeeld) setLaadStatus('laden');
    }
  } catch {
    setLijstFase(null);   // geen eerste beeld; fase 2 doet het werk
  }
  if (seq !== volgnummer) return;

  try {
    // Twee onafhankelijke lijsten, parallel: de volledige policylijst en de
    // versiecontainers die hun policysoort declareren. De tweede mag falen
    // (endpoint zonder die data of te traag): dan blijft de gewone lijst staan.
    const [rijen, cRijen] = await Promise.all([
      indexRijen(ep),
      sparqlSelect(ep, containerListQuery()).catch(() => [] as Binding[]),
    ]);
    if (seq !== volgnummer) return;
    setLijstFase(null);
    const ttl = listSkeletonTurtle(rijen) + containerSkeletonTurtle(cRijen);
    // Fase 2 bouwt de graaf vanaf nul. Wat er intussen is bijgeladen staat
    // in `bijgeladen` (collectieniveaus en kaartdetails) en wordt door
    // verwerkBronnen opnieuw ingemengd — niet meer als extra BRON, want dan telt
    // de statusregel hem mee (bevinding I-3).
    await verwerkBronnen(seq, metBasis([{
      name: `${ep} (policylijst, ${rijen.length} rijen`
        + (cRijen.length ? ` + ${cRijen.length} versierijen` : '') + ')',
      url: ep, content: ttl, format: 'ttl', fromSparql: true,
    }]), metBasisFouten([]), opties);
    if (seq !== volgnummer) return;
    // Aanbod en overeenkomsten zijn er doorgaans weinig en hun secties staan
    // open: hun details meteen bijhalen, anders tonen ze alleen het skelet.
    await haalKaartDetails(seq);
  } catch (e) {
    if (seq !== volgnummer) return;
    setLijstFase(null);
    const msg = e instanceof Error ? e.message : String(e);
    // WELKE slag faalde bepaalt beide meldingen (bevinding M-2). Mét eerste
    // beeld blijft dat staan (setModel wordt niet geraakt) en meldt de
    // statusregel err.sparqlFullIndex met de kaartmelding err.fullIndex ernaast;
    // zonder eerste beeld is het de gewone endpoint-fout. Dat onderscheid komt
    // hier uit de lading zelf, niet uit "staat er toevallig nog een model".
    setLijstFout(eersteBeeld ? 'volledigeIndex' : 'endpoint');
    // IN DE UNIE STAAT DE BESTANDSHELFT ER NOG, en haar fouten horen niet door
    // een endpointfout te worden weggepoetst. Het MODEL blijft ook staan
    // (setModel wordt hier niet geraakt): de foutstand met een leesbaar corpus
    // eronder is precies de "beter iets dan niets"-stand die de fase-2-fout van
    // de zuivere endpointstand al kent.
    setFouten(metBasisFouten([{ url: ep, message: msg }]));
    setLaadStatus('fout');
  }
}

// --- DE FORMULIER-SHAPES VAN HET ENDPOINT ------------------------------------
//
// EIGENAARSMELDING 14 SEP 2026 ("geen foldouts meer en allerlei gegevens
// kwijt, in sparql endpoint tenminste"). De shapes ZITTEN in het endpoint —
// `docker/fuseki/load.sh` zet de shapes bij de voorbeelden in de dataset, precies
// zoals note §8 voorschrijft — maar geen enkele query van deze store vroeg
// erom. De weergave leest ze uit de clientgraaf (`readShapes` in forms.js), en
// die kende alleen policies: geen shape, geen dekking, geen vouw, geen telling.
//
// DE FETCH LOOPT PARALLEL MET DE LADING EN MENGT ERNA. De graaf bestaat pas na
// de modelbouw, dus het ophalen (netwerk) start meteen en het mengen wacht op
// `graafGereed`. Het materiaal gaat door dezelfde `bijgeladen`-lijst als de
// verkennerknopen en de kaartdetails: het is GEEN bron (de lezer wees het niet
// aan, het heeft geen eigen adres), en zo overleeft het de her-ingest van
// fase 2 zonder de bronnentelling te verhogen.
const VORM_SHAPES_SLEUTEL = 'urn:odrlvis:vormshapes';
const LABELS_SLEUTEL = 'urn:odrlvis:knooplabels';

interface VormShape { targetClass: string }
const leesShapes = readShapes as unknown as (g: Graaf) => VormShape[];
// DE MEEGELEVERDE ARTEFACTSHAPE HOORT IN DEZELFDE TABEL als in
// `ui/kaart/formulier-model.ts` (15 sep 2026): sinds de artefacttak van de
// conformsToPolicy-rij verviel is dat de shape die artefacten dekt, en een
// telling die hem hier weglaat zou in endpointmodus een ander getal geven dan de
// weergave ernaast toont.
const meegeleverdeShapes = builtinShapes as unknown as (ttl: string[]) => VormShape[];
const gedekteKlassen = coveredClasses as unknown as (
  g: Graaf, shapes: VormShape[]) => Set<string>;
const gedekteKnopenUit = coveredNodes as unknown as (
  g: Graaf, klassen: Set<string>, opties?: { skipGraphs?: string[] },
) => { iris: Set<string>; blanks: number };
const heeftEigenNaam = hasOwnLabel;

/** De shapes OPHALEN, zonder te mengen. Faalt de query (een endpoint zonder
 *  SHACL, een 500), dan is het antwoord leeg: de pagina hoort daar niet van om
 *  te vallen — zij toont dan wat zij vóór deze taak ook toonde. */
function vormShapesTtl(ep: string): Promise<string> {
  return sparqlConstruct(ep, formShapesQuery({ excludeGraphs: laatsteExcludeGraphs }))
    .catch(() => '');
}

/** De opgehaalde shapes in de graaf mengen, en daarna de telling ophalen. */
async function mengVormShapes(seq: number, ep: string, belofte: Promise<string>): Promise<void> {
  const ttl = await belofte;
  if (seq !== volgnummer || !ttl || !ttl.trim()) return;
  await graafGereed;
  if (seq !== volgnummer) return;
  const g = graaf();
  if (!g) return;
  setBijgeladen((l) => [...l, { iri: VORM_SHAPES_SLEUTEL, ttl, ep }]);
  addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
  setGraafVersie((v) => v + 1);
  // De dekkingstabel wordt hier één keer gebouwd en door beide vervolgstappen
  // gebruikt: de telling en de labelhaler stellen dezelfde vraag aan de graaf.
  const klassen = gedekteKlassen(g,
    [...leesShapes(g), ...meegeleverdeShapes([ARTIFACT_FORM_SHAPE_TTL])]);
  await Promise.all([
    telGedekteKnopen(seq, ep, g, klassen),
    haalOntbrekendeLabels(seq, ep, g, klassen),
  ]);
}

/** DE LABELS VAN GEDEKTE KNOPEN DIE ER NOG GEEN HEBBEN (addendum 1, 14 sep 2026).
 *
 *  Eigenaar: "Ik zie ook soms dat een attribuut eerst als identifier getoond
 *  wordt (component-xxx had het volgens mij) en na het openklappen ineens een
 *  titel krijgt. Kan dat niet gelijk meegequeried worden? Of was dat een
 *  ttl+sparql mix artifact?"
 *
 *  DIAGNOSE (gemeten, `label-diagnose.mjs`): het was een mix-artefact, en wel de
 *  ASYMMETRISCHE mix. Een ttl die de STRUCTUUR draagt — de knoop staat er mét
 *  rdf:type, dus hij is gedekt en krijgt zijn vouw — naast een endpoint dat de
 *  BESCHRIJVING draagt. De kop rendert dan meteen uit de clientgraaf, waar
 *  `labelFor` niets vindt dan de localName, en het label komt pas mee met de
 *  pay-per-open-hop van `nodeFormQuery`. Op de Vlierdamse GLO: zuiver bestand 0
 *  flitsen, zuiver endpoint 0, asymmetrisch gemengd honderden.
 *
 *  De reparatie is één begrensde CONSTRUCT bij de lading, voor precies de knopen
 *  waarvan de client wél weet dát ze gedekt zijn en niet HOE ze heten. Het is
 *  dezelfde lijst die de telling hierboven als uitsluiting gebruikt, dus hij
 *  kost geen extra rekenwerk op de graaf.
 *
 *  RULING 5 VAN endpoint-domainforms BLIJFT STAAN: dit haalt alleen
 *  LABELpredicaten vooruit, niet het kerngegeven (`dash:KeyInfoRole`) en niet de
 *  sluiting van de knoop. Een label is wat er staat waar de lezer kijkt; de
 *  KeyInfo-badge is een extra, en die blijft pay-per-open. */
async function haalOntbrekendeLabels(
  seq: number, ep: string, g: Graaf, klassen: Set<string>,
): Promise<void> {
  try {
    const naamloos = [...gedekteKnopenUit(g, klassen).iris]
      .filter((iri) => !heeftEigenNaam(g, iri));
    const q = nodeLabelsQuery(naamloos, { excludeGraphs: laatsteExcludeGraphs });
    if (!q) return;
    const ttl = await sparqlConstruct(ep, q);
    if (seq !== volgnummer || !ttl || !ttl.trim()) return;
    await graafGereed;
    if (seq !== volgnummer) return;
    // EERST in de bijlaadlijst, dan pas mengen — dezelfde volgorde en dezelfde
    // lijst als de shapes en de knoopsluitingen (bevinding M-4). Geen bron: de
    // lezer wees dit materiaal niet aan en het heeft geen eigen adres (I-3).
    setBijgeladen((l) => [...l, { iri: LABELS_SLEUTEL, ttl, ep }]);
    const nu = graaf();
    if (!nu) return;
    addSource(nu, ttl, 'ttl', graphForSource({ url: ep }, 0));
    setGraafVersie((v) => v + 1);
    // DE LABELS MOETEN HET MODEL IN: een kaartrij toont de naam van een verwezen
    // knoop uit het MODEL, niet uit de graaf. Zonder deze herbouw staat de
    // localname er tot de volgende willekeurige herbouw.
    herbouwUitGraaf();
  } catch {
    // Geen labels is de stand van vóór deze reparatie: leesbaar genoeg om niet
    // de hele pagina voor om te laten vallen.
  }
}

/** "N gespecificeerd(e) object(en)" als ÉÉN SELECT. De klassen komen uit de
 *  dekkingstabel die zojuist uit de opgehaalde shapes is gebouwd — dus mét de
 *  subklasse-sluiting die met tak 4 van de shapes-CONSTRUCT meekwam, en in de
 *  unie mét de shapes die uit de BESTANDEN kwamen.
 *
 *  RULING (endpoint-domainforms, brief punt 3): één COUNT bij de lading, niet
 *  tellen over wat client-side bekend is. Beide zijn eerlijk, maar het tweede
 *  getal groeit terwijl de lezer klikt en zegt nooit hoe groot het geheel is —
 *  op het domeincorpus zou de regel bij 5 beginnen waar bestandsmodus 50 zegt, en
 *  dat is precies het "ik mis allerlei gegevens" dat de melding beschrijft.
 *
 *  IN DE UNIE IS HET EEN SOM VAN TWEE HELFTEN (14 sep 2026), en de kunst is dat
 *  de overlap niet twee keer telt. De BESTANDSkant staat volledig in de graaf en
 *  telt de client dus zelf — mét `skipGraphs`, zodat het endpointmateriaal (dat
 *  in de graph van het endpoint staat en groeit terwijl de lezer klikt) er
 *  buiten blijft en dit getal stabiel is. Die knopen gaan vervolgens als
 *  uitsluiting mee in de COUNT, zodat het endpoint alleen telt wat de client nog
 *  NIET kent. Een knoop die in beide bronnen staat — de GLO's van de eigenaar
 *  staan in het endpoint én als ttl — telt daarmee precies één keer.
 *
 *  Kost bij ongelijk: één SELECT per endpointlading, deze functie en één
 *  `NOT IN`-clausule. In de zuivere endpointstand is de uitsluiting leeg (alles
 *  staat in de endpoint-graph) en is de query letterlijk die van vóór deze
 *  ronde. */
async function telGedekteKnopen(
  seq: number, ep: string, g: Graaf, klassen: Set<string>,
): Promise<void> {
  try {
    const uitBestand = gedekteKnopenUit(g, klassen,
      { skipGraphs: [String(graphForSource({ url: ep }, 0))] });
    // Alleen IRI's kunnen de lijn over; een gedekte BLANKE knoop uit een bestand
    // kan per constructie nooit dezelfde zijn als een blanke knoop van het
    // endpoint, dus hij telt wél mee en hoeft niet uitgesloten te worden.
    const q = coveredCountQuery(klassen, {
      excludeGraphs: laatsteExcludeGraphs, excludeNodes: uitBestand.iris,
    });
    // `null` = geen gedekte klassen, of een bestandshelft die te groot is voor
    // een eerlijke uitsluiting (COVERED_COUNT_MAX_EXCLUDE). In beide gevallen
    // geen endpointtelling: `gedekteKnopen()` telt dan zoals in bestandsmodus.
    if (!q) return;
    const rijen = await sparqlSelect(ep, q);
    if (seq !== volgnummer) return;
    const n = parseInt((rijen[0] && rijen[0].n && rijen[0].n.value) || '', 10);
    if (!Number.isFinite(n)) return;
    const totaal = n + uitBestand.iris.size + uitBestand.blanks;
    if (totaal > 0) setGedektTelling(totaal);
  } catch {
    // Geen telling is beter dan een verkeerde: de regel laat het segment weg,
    // precies als op een corpus zonder formulier-shapes.
  }
}

async function laadVanEndpoint(
  seq: number, ep: string, policyScope: string | null, opties: BouwOpties,
): Promise<void> {
  // Het netwerk mag meteen aan het werk: de shapes hangen niet aan de lijst en
  // de lijst niet aan de shapes.
  const shapes = vormShapesTtl(ep);
  try {
    if (policyScope) {
      const ttl = await sparqlConstruct(ep,
        policyDetailQuery(policyScope, { excludeGraphs: laatsteExcludeGraphs }));
      if (seq !== volgnummer) return;
      await verwerkBronnen(seq, metBasis([{
        name: `${ep} (policy-detail)`, url: ep, content: ttl, format: 'ttl', fromSparql: true,
      }]), metBasisFouten([]), opties);
      return;
    }
    await laadPolicyLijst(seq, ep, opties);
  } catch (e) {
    setLijstFout('endpoint');
    meldFout(seq, { url: ep, message: e instanceof Error ? e.message : String(e) });
  } finally {
    // OOK NA EEN FOUT, en ook na de vroege `return` van de ?policy=-route: de
    // shapes zijn los van de lijst, en een kaart die er wél staat hoort zijn
    // vouwen te krijgen. Een `finally` is de enige plek die alle drie de
    // uitgangen dekt.
    await mengVormShapes(seq, ep, shapes);
  }
}

/** Laad een corpus. Synchroon in de aanroep (de store vertelt de voortgang);
 *  een tweede aanroep maakt een lopende lading ongeldig.
 *
 *  Drie ingangen, in de volgorde van het boot-blok van de bevroren viewer:
 *  bronnen winnen, dan het endpoint, dan de scope-IRI als bron. */
export function laadCorpus(params: {
  /** ?src=: de GENERIEKE ingang. Elke waarde wordt gedetecteerd — een bestand
   *  wordt geladen, een endpoint gaat de endpointroute in. */
  src: string[];
  /** ?ttl=: de legacy-alias die ALTIJD een bestand is (geen detectie). */
  ttl?: string[];
  sparql?: string | null;
  policyScope?: string | null;
  setScope?: string | null;
  lang?: string;
  excludeGraphs?: string[];
}): void {
  const seq = ++volgnummer;
  // Geen ?src=/?ttl=, geen endpoint en geen scope-IRI? Dan blijft de lijst leeg
  // — zie teLadenBronnen, waar de demo-tak op 9 sep 2026 is vervallen.
  const urls = teLadenBronnen({
    src: params.src || [],
    ttl: params.ttl || [],
    sparql: params.sparql ?? null,
    scope: params.policyScope ?? params.setScope ?? null,
  });
  // De oude ingest geeft allebei aan de worker mee (doc.js: loadSourcesInWorker
  // met { setScope, lang }): de worker bouwt het model én de gescopete nav, en
  // moet dus dezelfde taal en dezelfde ?set=-scope kennen als de pagina.
  const setScope = params.setScope ?? null;
  const policyScope = params.policyScope ?? null;
  const ep = params.sparql || null;
  const lang = params.lang ?? getLang();
  const opties: BouwOpties = { setScope, policyScope, lang };
  laatsteSetScope = setScope;
  laatstePolicyScope = policyScope;
  laatsteRuweExclude = params.excludeGraphs;
  setGraaf(null);
  graafGereed = Promise.resolve();
  setFouten([]);
  basisBronnen = [];
  basisFouten = [];
  noteerEndpoint(ep);
  // Elke lading begint als bestandslading; de twee endpointroutes hieronder
  // zetten hem aan zodra zíj het worden.
  setEndpointIsBron(false);
  setLijstFase(null);
  setLijstFout(null);
  setCompatIndex(false);
  setBijgeladen([]);
  niveauGeladen.clear();
  detailGeladen.clear();
  detailBezig.clear();
  knoopVormGeladen.clear();
  setGedektTelling(null);

  if (!urls.length && !ep && !(policyScope || setScope)) {
    // DE LEGE START. Tot 9 sep 2026 was deze tak vrijwel onbereikbaar — hij ging
    // alleen aan bij een uitrol met een leeg voorbeeldcorpus — maar sinds de
    // demo-tak in `teLadenBronnen` is vervallen, is dit de NORMALE opening van de
    // app: geen parameters, geen bronnen, een leeg werkblad. Het bronnenpaneel
    // gaat hier open staan met zijn lege-staat-melding (src/app.tsx); de
    // statusregel meldt 'leeg'.
    setModel(null); setBronnen([]); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setLaadStatus('leeg');
    return;
  }
  setLaadStatus('laden');
  if (urls.length) {
    setLaadMelding('load.sources');
    void laadBestanden(seq, urls, opties);
    return;
  }
  if (ep) {
    // De bevroren viewer zet hier het endpoint in de melding zelf
    // (doc.js r.11251: `t('load.queryEndpointAt', { ep })`).
    setLaadMelding('load.queryEndpointAt');
    setEndpointIsBron(true);
    void laadVanEndpoint(seq, ep, policyScope, opties);
    return;
  }
  // Eén scope-IRI is één bron: enkelvoud, zoals doc.js r.11726 (bevinding M-5).
  setLaadMelding('load.source');
  void laadScopeBron(seq, (policyScope || setScope)!, opties);
}

// --- Het DETAIL van één kaart (endpointmodus) --------------------------------
// De lijst-SELECT levert een skelet: titel, afnemer, datering — geen regels. De
// regels van één policy komen pas als de lezer haar kaart openklapt, met één
// CONSTRUCT (policyDetailQuery). Dat is `ensureDetail` uit de bevroren viewer;
// hij hoort bij de kaartenlijst, en verhuist daarom met die lane mee.
//
// Twee administraties, precies als daar: `detailGeladen` (dit hebben we al) en
// `detailBezig` (hier wordt al aan gewerkt — twee kaarten die tegelijk
// openklappen mogen niet twee keer hetzelfde ophalen). Beide worden bij elke
// nieuwe lading gewist, want ze slaan op de graaf van díe lading.

const detailGeladen = new Set<string>();
const detailBezig = new Map<string, Promise<boolean>>();

/** Heeft deze policy in endpointmodus nog een detail nodig? Een stub-versie
 *  niet: die heeft per definitie geen regels in de bron, dus een CONSTRUCT
 *  erop zou telkens leeg terugkomen. */
export function detailNodig(pol: {
  iri?: string; anon?: boolean; stub?: boolean;
  permissions?: unknown[]; prohibitions?: unknown[]; obligations?: unknown[];
} | null): boolean {
  if (!endpoint() || !pol || !pol.iri || pol.anon || pol.stub) return false;
  if (detailGeladen.has(pol.iri)) return false;
  return !((pol.permissions && pol.permissions.length)
    || (pol.prohibitions && pol.prohibitions.length)
    || (pol.obligations && pol.obligations.length));
}

/** CONSTRUCT het detail van één policy en meng het in de graaf. `herbouwModel`
 *  false laat het model met rust — voor een batch, die er ná afloop één
 *  herbouw overheen doet. `true` = er kwam iets bij. */
export async function haalDetail(
  iri: string, opties: { herbouwModel?: boolean } = {},
): Promise<boolean> {
  const ep = endpoint();
  if (!iri || !ep || detailGeladen.has(iri)) return false;
  const bezig = detailBezig.get(iri);
  if (bezig) return bezig;
  const seq = volgnummer;
  const p = (async () => {
    const ttl = await sparqlConstruct(ep,
      policyDetailQuery(iri, { excludeGraphs: laatsteExcludeGraphs }));
    // Worker-pad: wacht tot de hoofddraad-graaf gevuld is voordat we er iets
    // bij mengen — een model uit een half opgebouwde store zou policies laten
    // verdwijnen.
    await graafGereed;
    if (seq !== volgnummer) return false;
    const g = graaf();
    if (!g) throw new Error(t('load.graph'));
    // EERST in de bijlaadlijst, dan pas mengen — dezelfde volgorde en dezelfde
    // lijst als de knoop-CONSTRUCT hierboven (bevinding M-4). Het detail is
    // GEEN bron: de lezer wees het niet aan, en de bronnentelling van de
    // statusregel hoort niet te verspringen omdat iemand een kaart uitklapt
    // (bevinding I-3).
    setBijgeladen((l) => [...l, { iri, ttl, ep }]);
    addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
    detailGeladen.add(iri);
    setGraafVersie((v) => v + 1);
    if (opties.herbouwModel !== false) herbouwUitGraaf();
    return true;
  })();
  detailBezig.set(iri, p);
  try { return await p; } finally { detailBezig.delete(iri); }
}

/** MEERDERE DETAILS IN ÉÉN BEURT: parallel ophalen, ÉÉN modelherbouw erna.
 *
 *  EIGENAARSMELDING 14 SEP 2026 ("versies zijn niet echt meer navigeerbaar,
 *  super traag / lijkt niks te gebeuren"). Eén versiehop haalt niet één maar een
 *  handvol details op: van de policy waar de lezer staat, en — bij een
 *  STUB-versie, waar de inhoud op zijn bronnen hangt — van elk van die bronnen.
 *  `Versienav` deed dat in een `for`-lus met `await` erin, dus strikt
 *  achter elkaar, en elke ronde deed er bovendien een volle `buildModel`
 *  overheen.
 *
 *  GEMETEN op de staande /brp (3,4 M triples, `meet-paar.mjs` in de
 *  dt4-workspace): één versieklik = 7 detailqueries, samen 10 kB en 10,8-13,0 s
 *  wandklok, waarvan ~7,7 s pure wachttijd (CDP-profiel: `idle` 48,8%). De
 *  bytes zijn dus niet het probleem — de zeven ritjes achter elkaar zijn het.
 *
 *  Dit is de vorm die `haalKaartDetails` hieronder al had: `Promise.all` met
 *  `herbouwModel: false`, en daarna één keer `herbouwUitGraaf`. Zelfde
 *  semantiek, zelfde eindstand van de graaf, één wachttijd in plaats van N.
 *  Een mislukte hop laat de rest staan en wordt door de aanroeper gemeld. */
export async function haalDetails(iris: readonly string[]): Promise<boolean> {
  const lijst = [...new Set(iris.filter(Boolean))];
  if (!lijst.length || !endpoint()) return false;
  const seq = volgnummer;
  const uit = await Promise.all(
    lijst.map((iri) => haalDetail(iri, { herbouwModel: false })));
  if (seq !== volgnummer) return false;
  if (uit.some(Boolean)) herbouwUitGraaf();
  return uit.some(Boolean);
}

/** Model + nav opnieuw uit de (bijgemengde) graaf. Zonder fetch, zonder
 *  her-parse — de goedkope helft van `herbouw`, zonder het wachten. */
function herbouwUitGraaf(): void {
  const g = graaf();
  if (!g) return;
  const m = buildModel(g);
  const n = buildNav(m);
  setModel(m);
  setNav(() => n);
  setScopedNav(() => eigenScoping(n, huidigeScope()));
}

// --- DE GERICHTE INVALIDATIE (deeltraject 3, mutatiekern) --------------------
// CONTRACTWIJZIGING op deze store, en de reden dat zij hier staat: de
// bewerklaag muteert de GRAAF, maar de weergave tekent het MODEL. De bevroren
// viewer overbrugt dat met `herrenderNu`: één volle `buildModel` per mutatie,
// over het hele corpus, gevolgd door een volledige hertekening — de gemeten
// bottleneck van de architectuurverkenning (4 sep).
//
// Hier komt de mutatie binnen als DELTA, en beslist deze store wat er opnieuw
// gelezen moet worden:
//
//   * `gericht`  — de delta valt binnen kaarten die de weergave al kent: alleen
//                  die kaartmodellen worden opnieuw gelezen (parse.js:
//                  `buildModel(store, {hergebruik, alleen})`), en de
//                  navigatierijen die er niet van veranderen houden hun
//                  identiteit, zodat de UI ze niet hoeft te hertekenen.
//   * `volledig` — de delta raakt iets buiten de kaartlaag (een artefact, een
//                  dataset, een labelbundel), of hij verandert de VERZAMELING
//                  policies (nieuw beleid, verwijderd beleid). Dan is er geen
//                  veilige deelherbouw en gaat de volle `buildModel` alsnog —
//                  LUID, want een stille terugval verbergt precies de gevallen
//                  waarin de perf-belofte niet opgaat.
//
// DE BELOFTE, PRECIES GEFORMULEERD: beide paden leveren hetzelfde model op
// ZOLANG DE TOEWIJZING VOLLEDIG IS. Dat "zolang" is geen slag om de arm maar de
// hele constructie: `geraaktePolicies` is niet bewijsbaar volledig, hij is
// getoetst — op de vormen in `model/test/deelherbouw.test.mjs` (speelgoedgraaf
// én breda), op de acht adversariële gevallen in
// `model/test/deelherbouw-adversarieel.test.mjs`, en hier in
// `corpus-invalidatie.test.ts`. Wat de belofte draagt is dat elke twijfel de
// kant van BREDER op valt, dat de globale slagen in parse.js hun eigen velden
// wissen vóór ze zetten (zodat een gemiste toewijzing repareerbaar blijft in
// plaats van te blijven plakken), en dat de poorten hieronder de rest luid
// opvangen.

export interface Invalidatie {
  modus: 'gericht' | 'volledig';
  /** De kaartmodellen die opnieuw gelezen zijn. Leeg bij een volledige herbouw:
   *  dan zijn ze het allemaal. */
  policies: string[];
  /** Waarom er volledig herbouwd is; leeg bij een gerichte invalidatie. */
  reden: string;
}

/** De policy-IRI's van het huidige model — de enige kaarten die gericht
 *  herbouwd kúnnen worden (wat de weergave nog niet kent, kent zij niet). */
function policyIris(m: Model): Set<string> {
  const uit = new Set<string>();
  for (const bak of [m.offers, m.agreements, m.sets]) {
    for (const p of (bak || []) as { iri?: string; anon?: boolean }[]) {
      if (p.iri && !p.anon) uit.add(p.iri);
    }
  }
  return uit;
}

const zelfdeVerzameling = (a: Set<string>, b: Set<string>): boolean => a.size === b.size
  && [...a].every((x) => b.has(x));

// Waardegelijkheid op de platte data van een navigatierij (strings, getallen,
// arrays, objecten). De boom draagt geen termen of functies, dus dit volstaat —
// en hij is er alleen om te kunnen zeggen "deze rij is niet veranderd".
function gelijkeWaarde(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((x, i) => gelijkeWaarde(x, b[i]));
  }
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false;
  const ao = a as Record<string, unknown>;
  const bo = b as Record<string, unknown>;
  const sleutels = Object.keys(ao);
  if (sleutels.length !== Object.keys(bo).length) return false;
  return sleutels.every((k) => gelijkeWaarde(ao[k], bo[k]));
}

interface NavRij { id?: string; label?: string; children?: NavRij[] }

/** Geef ONVERANDERDE navigatierijen hun oude object terug. De boom wordt bij
 *  elke herbouw opnieuw opgebouwd; wie hem met een sleutel op identiteit
 *  tekent, zou dan élke rij hertekenen terwijl er één titel veranderde. Rijen
 *  worden op `id` gepaard en alleen hergebruikt als ze ook werkelijk gelijk
 *  zijn — een verkeerde paring kan dus geen verouderde rij opleveren. */
function hergebruikRijen(oud: NavRij[] | null, nieuw: NavRij[]): NavRij[] {
  if (!oud || !oud.length) return nieuw;
  const perId = new Map<string, NavRij>();
  for (const r of oud) if (r && r.id) perId.set(r.id, r);
  return nieuw.map((r) => {
    const o = r && r.id ? perId.get(r.id) : undefined;
    if (!o) return r;
    const kinderen = hergebruikRijen(o.children || null, r.children || []);
    const kandidaat = kinderen === r.children ? r : { ...r, children: kinderen };
    return gelijkeWaarde(o, kandidaat) ? o : kandidaat;
  });
}

function zetBoom(m: Model, oudeNav: Nav): void {
  const n = buildNav(m);
  const gepaard = (Array.isArray(oudeNav) && Array.isArray(n))
    ? hergebruikRijen(oudeNav as NavRij[], n as NavRij[]) : n;
  setModel(m);
  setNav(() => gepaard as Nav);
  setScopedNav(() => eigenScoping(gepaard as Nav, huidigeScope()));
}

function volledigeHerbouw(reden: string, luid: boolean): Invalidatie {
  if (luid) console.warn(`corpus: volledige herbouw na een mutatie — ${reden}`);
  const g = graaf();
  if (g) {
    // MET RIJHERGEBRUIK, óók hier (review I-5). De terugval bouwt het model
    // vanaf nul — dat hoort, want dat is precies wat hij belooft — maar de
    // navigatieBOOM is dan vaak identiek, en hem toch vervangen laat de zijnav
    // bij elke terugval in zijn geheel hertekenen. Dat is de sprong die de
    // gerichte weg juist wegneemt, en de terugval is geen randgeval (een
    // gedeelde vocabulaireknoop haalt hem al). `hergebruikRijen` vergelijkt op
    // waarde, dus dit kan geen verouderde rij opleveren.
    zetBoom(buildModel(g), nav());
    setGraafVersie((v) => v + 1);
  }
  return { modus: 'volledig', policies: [], reden };
}

/** Verwerk één mutatiedelta: het model (en de nav) lopen weer gelijk met de
 *  graaf. Synchroon — de aanroeper (`stores/bewerk.ts`) bepaalt zelf wanneer
 *  hij de weergave laat bijkomen. */
export function invalideer(delta: Delta): Invalidatie {
  const g = graaf();
  const m = model();
  // Geen graaf of geen model: er valt niets te herbouwen. Geen waarschuwing —
  // dit is geen terugval maar een lege stand.
  if (!g || !m) return { modus: 'volledig', policies: [], reden: 'geen graaf of model' };
  const quads = [...(delta.added || []), ...(delta.removed || [])];
  // Een lege delta zegt niets over wat er veranderde. Dan is de veilige lezing
  // "alles kan veranderd zijn" — dezelfde regel als `hergebruik` zonder
  // `alleen` in parse.js.
  if (!quads.length) return volledigeHerbouw('lege delta', false);

  const vorigeIris = policyIris(m);
  const toewijzing = geraaktePolicies(g, delta, vorigeIris);
  const geraakt = toewijzing.policies;
  if (!geraakt) {
    // DE REDEN KOMT UIT DE TOEWIJZING (review I-3). "Buiten de kaartlaag" en
    // "de wandeling zakte door haar budget" zijn twee verschillende diagnoses:
    // de eerste zegt dat er niets te richten viel, de tweede dat de knoop te
    // veel verwijzers heeft — op een groot corpus de vaakst voorkomende, en een
    // console-regel die dan het eerste beweert stuurt de lezer de verkeerde kant
    // op.
    return volledigeHerbouw(toewijzing.reden === 'budget'
      ? 'de toewijzing zakte door haar knopenbudget'
      : 'mutatie buiten de bekende kaarten', true);
  }

  const nieuw = buildModel(g, { hergebruik: m, alleen: new Set(geraakt) });
  // DE POORT. Kwam er beleid bij of viel er beleid weg, dan kunnen HERGEBRUIKTE
  // kaarten verouderde verwijzingen dragen (een overeenkomst die naar een
  // verdwenen aanbod wijst) en klopt de deelherbouw niet meer. Het gerichte werk
  // is dan voor niets gedaan, maar dat is goedkoper dan een fout model.
  if (!zelfdeVerzameling(vorigeIris, policyIris(nieuw))) {
    return volledigeHerbouw('de verzameling policies veranderde', true);
  }
  zetBoom(nieuw, nav());
  // De KAARTEN lezen de graaf rechtstreeks; een mutatie moet ze meebewegen.
  setGraafVersie((v) => v + 1);
  return { modus: 'gericht', policies: geraakt, reden: '' };
}

// Aanbod- en overeenkomstdetails worden ná de lijst meteen bijgeladen: hun
// secties staan open en zouden anders alleen het skelet tonen. Begrensd, om een
// pathologisch endpoint niet plat te fetchen. Aanbod ALTIJD (begrensd);
// overeenkomsten alleen als het er weinig zijn — op schaal laadt hun kaart-
// uitklap het detail lui.
const EAGER_DETAIL_MAX = 20;

export async function haalKaartDetails(seq?: number): Promise<void> {
  const m = model() as unknown as { offers?: unknown[]; agreements?: unknown[] } | null;
  if (!endpoint() || !m) return;
  const aanbod = (m.offers || []).filter((p) => detailNodig(p as never))
    .slice(0, EAGER_DETAIL_MAX);
  const afspraken = (m.agreements || []).filter((p) => detailNodig(p as never));
  const pols = (aanbod.length + afspraken.length <= EAGER_DETAIL_MAX
    ? [...aanbod, ...afspraken] : aanbod) as Array<{ iri: string }>;
  if (!pols.length) return;
  // Parallel ophalen, één modelherbouw na afloop.
  await Promise.all(pols.map((p) => haalDetail(p.iri, { herbouwModel: false })
    .catch(() => false)));   // sectie blijft dan skelet; de uitklap meldt de fout
  if (seq !== undefined && seq !== volgnummer) return;
  herbouwUitGraaf();
}

// --- Eén niveau van de collectieboom bijladen (taak 6) ----------------------
// Zelfde vorm en zelfde reden als de knoop-CONSTRUCT van de verkenner, die hier
// tot 16 sep 2026 boven stond (gesloopt met de verkenner zelf): in endpointmodus
// is de geladen graaf op POLICIES gericht en weet hij van een collectie hooguit
// dát er leden zijn. Elk uitklappen kost daarom ÉÉN CONSTRUCT
// (collectionLevelQuery) met de leden, hun label/type en de lidmaatschappen één
// niveau dieper — zodat de boom weet wélke leden opnieuw uitklapbaar zijn.
//
// WAAROM HIER EN NIET IN DE COMPONENT: de query heeft `excludeGraphs` nodig, en
// dat is de uitgerekende lijst van deze lading — module-privé in deze store. Een
// component die hem zelf zou uitrekenen zou een tweede bron van waarheid zijn.

const niveauGeladen = new Set<string>();

/** Haal één collectieniveau bij van het endpoint. `false` = niets gedaan (geen
 *  endpoint, al geladen) of mislukt. Faalt de hop, dan toont de boom gewoon wat
 *  de graaf al heeft — een collectie met minder leden is een leesbaar
 *  antwoord, een lege weergave met een foutmelding niet. */
export async function haalCollectieNiveau(iri: string): Promise<boolean> {
  const ep = endpoint();
  if (!iri || !ep || niveauGeladen.has(iri)) return false;
  niveauGeladen.add(iri);
  try {
    const ttl = await sparqlConstruct(ep,
      collectionLevelQuery(iri, { excludeGraphs: laatsteExcludeGraphs }));
    await graafGereed;
    const g = graaf();
    if (!g) throw new Error(t('load.graph'));
    if (!ttl || !ttl.trim()) return false;
    // EERST in de bijlaadlijst, dan pas mengen — exact de volgorde en de lijst
    // van haalDetail hieronder. Een bijgeladen niveau is GEEN bron: de
    // lezer wees het niet aan en het heeft geen eigen adres, dus het hoort de
    // telling van de statusregel niet te verhogen (bevinding I-3). Via deze
    // lijst overleeft het wél de her-ingest van fase 2, wat de bronnenlijst
    // sinds diezelfde fixronde niet meer voor hem doet.
    setBijgeladen((l) => [...l, { iri, ttl, ep }]);
    addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
    setGraafVersie((v) => v + 1);
    return true;
  } catch {
    // Opnieuw proberen mag: dit niveau is niet geladen.
    niveauGeladen.delete(iri);
    return false;
  }
}

// --- De sluiting van ÉÉN gedekte knoop bijladen (eigenaarsmelding 14 sep) ----
// Zelfde vorm en dezelfde reden als `haalCollectieNiveau` hierboven, één laag
// verder: in endpointmodus kent de clientgraaf van een gedekte domeinknoop (een
// GLS, een leverset, een rol-object) hooguit zijn rdf:type en zijn label — dat
// is genoeg voor de AFFORDANCE maar te weinig voor het FORMULIER. Elke vouw die
// opengaat kost daarom ÉÉN CONSTRUCT (`nodeFormQuery`), en niets wordt vooruit
// gehaald: twintig afspraakknopen op één kaart zouden anders twintig sluitingen
// kosten voor iets wat de lezer niet opent. Pay-per-open is bij een endpoint
// precies de goede vorm.
//
// WAAROM HIER EN NIET IN DE COMPONENT: dezelfde reden als daar — de query heeft
// `excludeGraphs` nodig, en dat is de uitgerekende lijst van deze lading,
// module-privé in deze store.

const knoopVormGeladen = new Set<string>();

/** Haal de sluiting van één gedekte knoop bij van het endpoint. `false` =
 *  niets gedaan (geen endpoint, al geladen) of mislukt; het formulier toont dan
 *  wat de graaf al heeft. Eén keer per knoop: dichtklappen en opnieuw openen
 *  kost geen tweede hop. */
export async function haalKnoopVorm(iri: string): Promise<boolean> {
  const ep = endpoint();
  if (!iri || !ep || knoopVormGeladen.has(iri)) return false;
  knoopVormGeladen.add(iri);
  try {
    const ttl = await sparqlConstruct(ep,
      nodeFormQuery(iri, { excludeGraphs: laatsteExcludeGraphs }));
    await graafGereed;
    const g = graaf();
    if (!g) throw new Error(t('load.graph'));
    if (!ttl || !ttl.trim()) return false;
    // EERST in de bijlaadlijst, dan pas mengen — exact de volgorde en de lijst
    // van haalCollectieNiveau hierboven. Geen bron: de lezer
    // wees hem niet aan en hij heeft geen eigen adres (bevinding I-3).
    setBijgeladen((l) => [...l, { iri, ttl, ep }]);
    addSource(g, ttl, 'ttl', graphForSource({ url: ep }, 0));
    setGraafVersie((v) => v + 1);
    return true;
  } catch {
    // Opnieuw proberen mag: deze knoop is niet geladen.
    knoopVormGeladen.delete(iri);
    return false;
  }
}

// --- SEAM dt3 (lane-bronnen-edit): de bronnenlijst als MUTEERBARE lijst ------
// GEDOCUMENTEERDE CONTRACTWIJZIGING. De leesviewer van dt2 kent maar één weg
// naar een bronnenlijst: `laadCorpus(params)` uit de adresbalk. De bewerklaag
// heeft er een tweede nodig — de bronnenbalk voegt bronnen toe, gooit ze weg en
// zet ze op een lokale kopie — en dat is precies wat `syncAfterChange` in de
// bevroren viewer doet (doc.js r.9497): de lijst bijwerken en de store uit die
// lijst herbouwen. Die twee helften staan hier apart, want ze zijn niet
// hetzelfde:
//
//   zetBronnenLijst  — alleen de LIJST. Voor een modus-wissel (slotje om): de
//                      graaf verandert er niet van, en een her-ingest zou de
//                      bewerkingen sinds de vorige lading juist terugdraaien.
//   herlaadBronnen   — lijst én HER-INGEST. Voor een bron erbij of eraf.
//
// Wat hier NIET bij hoort en bewust bij de aanroeper blijft: het flushen van de
// autosave en het verversen van de OPFS-inhoud vóór de her-ingest (stap 1 en 2
// van syncAfterChange). Dat is bronnenlaag-werk; deze store weet niets van OPFS
// en hoort dat zo te houden.

/** Het bijgeladen ENDPOINTMATERIAAL van deze lading: de knoop-CONSTRUCTs van de
 *  collectieniveaus en de kaartdetails. GEEN bronnen — ze hebben
 *  geen eigen adres en tellen niet mee in de statusregel (bevinding I-3) — maar
 *  ze staan wél in de graaf, en wie een werkbestand maakt of een bron downloadt
 *  hoort te weten dat dit materiaal er is en NIET in zijn bestand belandt (het
 *  draagt de graph van het endpoint, niet die van zijn bron). Reactief: de
 *  lijst groeit terwijl de lezer het document uitklapt. */
export const bijgeladenKnopen: () => readonly { iri: string; ttl: string; ep: string }[] =
  bijgeladen;

/** Vervang de bronnenlijst ZONDER her-ingest. */
export function zetBronnenLijst(lijst: Bron[]): void {
  setBronnen(lijst);
}

/** Vervang de bronnenlijst MÉT her-ingest — de store wordt uit deze lijst
 *  herbouwd. Een lege lijst met een endpoint in beeld valt terug op de
 *  endpointlading, precies als `if (!sources.length && state.sparqlEndpoint)
 *  loadFromSparql()`. De belofte resolvet ná de modelbouw. */
export async function herlaadBronnen(lijst: Bron[]): Promise<void> {
  const seq = ++volgnummer;
  const opties: BouwOpties = {
    setScope: laatsteSetScope, policyScope: laatstePolicyScope, lang: getLang(),
  };
  setLaadStatus('laden');
  setFouten([]);
  // DE BESTANDSHELFT VAN DE UNIE KOMT VOORTAAN UIT DEZE LIJST, niet uit de
  // vorige lading: de bronnenbalk is precies de plek waar er een bron af gaat of
  // bij komt, en een endpointfase die daarna nog draait moet de NIEUWE lijst
  // terugleggen. De endpoint-pseudobronnen gaan er niet in — die schrijft de
  // endpointkant zelf weer bij.
  basisBronnen = lijst.filter((b) => !b.fromSparql);
  basisFouten = [];
  if (!lijst.length && endpoint()) {
    setBronnen([]);
    basisBronnen = [];
    setLaadMelding('load.queryEndpointAt');
    setEndpointIsBron(true);
    await laadVanEndpoint(seq, endpoint()!, laatstePolicyScope, opties);
    return;
  }
  if (!lijst.length) {
    setBronnen([]); setModel(null); setQuadCount(0); setMotor(null);
    setNav(null); setScopedNav(null);
    setLaadStatus('leeg');
    return;
  }
  // HIER GAAT DE LIJST ONGEWIJZIGD DE INGEST IN — inclusief de
  // endpoint-pseudobronnen die er al in stonden. Er is geen tweede
  // endpointronde nodig: hun `content` draagt het skelet en de detail-CONSTRUCTs
  // van deze lading al, en opnieuw bevragen zou de lezer een tweede
  // netwerkronde kosten voor materiaal dat hij al heeft (en, bij het VERWIJDEREN
  // van een bron, een flits van een leeg document).
  setLaadMelding('load.sources');
  await verwerkBronnen(seq, lijst, [], opties);
}

/** De VOORBEWERKING van elke verse bronnenlijst, vóór de ingest. De bronnenlaag
 *  hangt hier zijn OPFS-overlay aan (een bron met een lokale kopie komt uit die
 *  kopie, en de werkbestanden van deze browser komen erbij) — precies
 *  `metOpfsBronnen` in het boot-blok van de bevroren viewer (doc.js r.11712).
 *  Als REGISTRATIE en niet als import, zodat deze store niets van OPFS hoeft te
 *  weten en de bronnenlaag apart geladen kan worden. */
let voorbewerking: ((lijst: Bron[]) => Promise<Bron[]>) | null = null;

export function registreerBronVoorbewerking(
  fn: ((lijst: Bron[]) => Promise<Bron[]>) | null,
): void {
  voorbewerking = fn;
}

/** DE BACKSTOP-GRENS OP DE VOORBEWERKING (eigenaarsmelding 14 sep 2026: "Nu
 *  laadt hij het hele document niet meer als ik een nieuwe tab open").
 *
 *  Ruimer dan de eigen grens van de bronnenlaag (`OPFS_GRENS_MS`, 5 s), zodat
 *  die normaal gesproken als eerste afgaat en zijn eigen, betere melding kan
 *  geven. Deze grens hoort alleen af te gaan als een voorbewerking haar eigen
 *  belofte niet nakomt. */
const VOORBEWERK_GRENS_MS = 8000;

/** Het antwoord van `voorbewerkt`: de lijst waarmee doorgeladen wordt, plus de
 *  melding als de voorbewerking NIET geleverd heeft. Een tuple en geen stille
 *  vlag, omdat de aanroeper die melding in `extraFouten` moet leggen — anders
 *  kijkt de lezer naar de originele bronnen terwijl zijn lokale kopie bestaat,
 *  en zegt niets hem dat. */
interface Voorbewerkt { lijst: Bron[]; fout: CorpusFout | null }

/** Pas de geregistreerde voorbewerking toe; faalt zij, dan de lijst zoals hij
 *  was — een kapotte OPFS mag geen lege pagina opleveren.
 *
 *  EN DAT GELDT NU OOK VOOR EEN VOORBEWERKING DIE NOOIT ANTWOORDT. Hier stond
 *  een kale `await`: de `catch` ving een AFWIJZING, maar een belofte die nooit
 *  settelt wordt door geen enkele catch gevangen. Deze aanroep staat op het
 *  kritieke pad van élke bestandslading (`laadBestanden`), dus een hangende
 *  OPFS-lezing — een tweede tabblad achter een exclusieve handle van het eerste
 *  — hield de hele documentopbouw tegen: geen kaarten, geen fout, geen melding,
 *  alleen "laden". Dat is precies het beeld dat de eigenaar meldde.
 *
 *  DE UITWEG IS WERKEN MET WAT ER IS, HARDOP. De originele bronnen zijn al
 *  opgehaald; daarmee is het document te bouwen. Wat de lezer dan NIET ziet is
 *  zijn lokale kopie, en dat is te belangrijk om te verzwijgen — vandaar een
 *  melding in `fouten` in plaats van een stille terugval. */
async function voorbewerkt(lijst: Bron[]): Promise<Voorbewerkt> {
  if (!voorbewerking) return { lijst, fout: null };
  let klok: ReturnType<typeof setTimeout> | null = null;
  const TRAAG = Symbol('voorbewerking te traag');
  try {
    const grens = new Promise<typeof TRAAG>((r) => {
      klok = setTimeout(() => r(TRAAG), VOORBEWERK_GRENS_MS);
    });
    const uit = await Promise.race([voorbewerking(lijst), grens]);
    if (uit === TRAAG) {
      return { lijst, fout: { message: t('err.bronnenlaagTraag') } };
    }
    return { lijst: uit, fout: null };
  } catch {
    return { lijst, fout: null };
  } finally {
    if (klok !== null) clearTimeout(klok);
  }
}
