// ODRL-viewer — GENERIEKE, SHAPE-GEDREVEN FORMULIEREN ("domain forms").
//
// Een policy wijst naar knopen die een generieke tool niet kent: het artefact
// achter een realisatielink, een veldencollectie, een register. Labels
// (Visualisation Note §1) geven zo'n knoop een naam; een FORMULIERSHAPE zegt
// hoe zijn eigenschappen getoond horen te worden. Zie note §8 "Domain forms".
//
// Dit bestand leest zo'n shape en levert een WEERGAVEMODEL — geen DOM. De
// scheiding is met opzet: het model is in node te testen zonder DOM-stub, en
// doc.js beslist hoe een rij eruitziet (kv-blok, link met target=_blank,
// monospace). Alles wat presentatie is, staat dus NIET hier.
//
// SUBSET (precies wat de note §8 vastlegt):
//   SHACL   sh:NodeShape + sh:targetClass (met rdfs:subClassOf-sluiting),
//           sh:property met sh:path (ook [ sh:inversePath … ]), sh:name,
//           sh:description, sh:order, sh:group + sh:PropertyGroup
//   DASH    dash:viewer   {Literal,URI,Label,LangString}Viewer
//           dash:propertyRole {Label,Description,KeyInfo}Role
//   SHUI    dezelfde termen uit de W3C-draft SHACL 1.2 UI worden als SYNONIEM
//           gelezen (shui:viewer/shui:propertyRole; shui:IRIViewer ==
//           dash:URIViewer). Annoteren doen we in dash:, want dat werkt vandaag.
//
// Wat NIET in de subset zit is geen gebrek maar presentatie: kleuren,
// monospace, hoe een noot wordt omkaderd. sh:pattern staat in een shape als
// validatiegegeven; een tool MAG hem lezen als "deze waarde heeft een
// machinesyntaxis" — dat doet doc.js, en het is een tool-keuze, geen
// vocabulaireterm.
//
// VOLGORDE (SHUI §Grouping): groepen en ongegroepeerde properties staan in ÉÉN
// reeks, gesorteerd op sh:order; een groep neemt de sh:order van haar
// sh:PropertyGroup. Zonder order: achteraan, in bronvolgorde.

import * as N3 from 'n3';
import { pickLabel } from './i18n.js';
import { labelFor, localName, descriptionFor } from './parse.js';

const { DataFactory, Store, Parser } = N3;
const { namedNode } = DataFactory;

const SH = 'http://www.w3.org/ns/shacl#';
const DASH = 'http://datashapes.org/dash#';
const SHUI = 'http://www.w3.org/ns/shacl-ui/';
const RDF = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
const RDFS = 'http://www.w3.org/2000/01/rdf-schema#';
const SKOS = 'http://www.w3.org/2004/02/skos/core#';

// --- Kleine graaf-helpers ---------------------------------------------------
const objs = (store, s, p) => store.getQuads(s, namedNode(p), null, null).map((q) => q.object);
const obj = (store, s, p) => objs(store, s, p)[0] || null;
const isLiteral = (term) => !!term && term.termType === 'Literal';

// dash: en shui: zijn uitwisselbaar; shui:IRIViewer heet bij DASH URIViewer.
function annotation(store, node, pred) {
  const v = obj(store, node, DASH + pred) || obj(store, node, SHUI + pred);
  if (!v || v.termType !== 'NamedNode') return null;
  return localName(v.value).replace(/^IRIViewer$/, 'URIViewer');
}

// --- Het shapes-model -------------------------------------------------------

// Eén sh:property. `path` is null wanneer het pad iets is dat deze subset niet
// kent (een sequence path bijvoorbeeld) — zo'n property wordt overgeslagen in
// plaats van half getoond.
function readPropertyShape(store, node) {
  const pathTerm = obj(store, node, SH + 'path');
  let path = null;
  let inverse = false;
  if (pathTerm && pathTerm.termType === 'NamedNode') {
    path = pathTerm.value;
  } else if (pathTerm) {
    const inv = obj(store, pathTerm, SH + 'inversePath');
    if (inv && inv.termType === 'NamedNode') { path = inv.value; inverse = true; }
  }
  const orderTerm = obj(store, node, SH + 'order');
  const order = orderTerm && Number.isFinite(parseFloat(orderTerm.value))
    ? parseFloat(orderTerm.value) : null;
  const groupTerm = obj(store, node, SH + 'group');
  return {
    path,
    inverse,
    names: objs(store, node, SH + 'name').filter(isLiteral),
    descriptions: objs(store, node, SH + 'description').filter(isLiteral),
    order,
    group: groupTerm && groupTerm.termType === 'NamedNode' ? groupTerm.value : null,
    // sh:pattern is een validatiegegeven; de weergave mag het als aanwijzing
    // gebruiken (zie de kop van dit bestand).
    pattern: (obj(store, node, SH + 'pattern') || {}).value || null,
    viewer: annotation(store, node, 'viewer'),
    role: annotation(store, node, 'propertyRole'),
  };
}

// Alle sh:NodeShapes met een sh:targetClass uit een graaf.
export function readShapes(store) {
  const seen = new Set();
  const out = [];
  for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(SH + 'NodeShape'), null)) {
    const iri = q.subject.value;
    if (seen.has(iri)) continue;
    seen.add(iri);
    const target = obj(store, q.subject, SH + 'targetClass');
    if (!target || target.termType !== 'NamedNode') continue;
    out.push({
      iri,
      store,
      targetClass: target.value,
      properties: objs(store, q.subject, SH + 'property').map((n) => readPropertyShape(store, n)),
    });
  }
  return out;
}

// --- Doelklasse-matching ----------------------------------------------------
// Zelfde patroon als policyKinds in parse.js: een fixpunt over rdfs:subClassOf
// in de GEGEVENSgraaf, zodat een profiel zijn subklassen als data kan meebrengen
// (apnl:RegoModule rdfs:subClassOf apnl:PolicyArtifact).
function subclassClosure(dataStore, cls) {
  const seen = new Set([cls]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const q of dataStore.getQuads(null, namedNode(RDFS + 'subClassOf'), null, null)) {
      if (seen.has(q.object.value) && !seen.has(q.subject.value)) {
        seen.add(q.subject.value);
        changed = true;
      }
    }
  }
  return seen;
}

// EEN SHAPE MET WEERGAVE-ANNOTATIES IS EEN FORMULIER; een shape met alleen
// constraints is dat niet.
//
// Eén SHACL-bestand draagt vaak beide: toetsregels (sh:minCount, sh:pattern,
// sh:class) en daarnaast — op dezelfde sh:targetClass — een shape die zegt hoe
// de knoop getoond hoort te worden. De note §8 noemt precies zes termen die dat
// laatste doen; draagt geen enkele property er één van, dan zegt de shape niets
// over weergave en is zij als formulier een slechtere keuze dan een shape die
// dat wél doet.
//
// GEMETEN (Deel-C-lane, bevinding B1): met het hele shapes-bestand van een
// domeinprofiel geladen won overal de validatieshape, omdat zij eerder in het
// bestand staat — `GlsShape` in plaats van `GlsFormShape`, `GlpShape` in plaats
// van `GlpFormShape`. De kaart viel niet om (een validatieshape draagt sh:path,
// dus de rijen kregen hun label uit het vocabulaire), maar volgorde, groepen,
// kaartkop, kerngegeven en widgets waren weg.
const WEERGAVE_ANNOTATIES = ['name', 'description', 'order', 'group'];
export function isFormShape(shape) {
  return shape.properties.some((ps) => ps.viewer || ps.role
    || WEERGAVE_ANNOTATIES.some((k) => (k === 'name' ? ps.names.length
      : (k === 'description' ? ps.descriptions.length : ps[k] !== null))));
}
const isForm = isFormShape;

// De shape die bij deze knoop hoort, of null. Een shape uit `shapes` WINT van
// een gelijke uit `fallbacks` (zelfde sh:targetClass): een bron die haar eigen
// formulier meebrengt, bepaalt hoe het eruitziet. Bij meer dan één passende
// shape wint de meest SPECIFIEKE doelklasse — die het minst ver van de knoop
// af staat in de subklasse-hiërarchie; bij gelijke afstand de shape die
// WEERGAVE-ANNOTATIES draagt (zie hierboven), en anders de eerst gevonden.
//
// De volgorde van die twee sleutels is niet omkeerbaar: de doelklasse zegt
// WAAROVER een shape gaat, de annotaties zeggen alleen HOE ze het opschrijft.
// Een formulier op de bovenklasse mag een shape op de eigen klasse van de knoop
// dus niet verdringen.
export function shapeForNode(dataStore, termOrIri, shapes, fallbacks = []) {
  const term = typeof termOrIri === 'string' ? namedNode(termOrIri) : termOrIri;
  const types = new Set(objs(dataStore, term, RDF + 'type')
    .filter((o) => o.termType === 'NamedNode').map((o) => o.value));
  if (!types.size) return null;
  const kandidaten = [];
  const overridden = new Set();
  for (const s of shapes) overridden.add(s.targetClass);
  for (const s of [...shapes, ...fallbacks.filter((f) => !overridden.has(f.targetClass))]) {
    // De annotatiestand wordt hier ÉÉN keer per kandidaat bepaald en niet in de
    // vergelijkfunctie: die draait O(n log n) keer over dezelfde shape.
    if (types.has(s.targetClass)) { kandidaten.push([0, isForm(s) ? 0 : 1, s]); continue; }
    const closure = subclassClosure(dataStore, s.targetClass);
    if ([...types].some((ty) => closure.has(ty))) kandidaten.push([1, isForm(s) ? 0 : 1, s]);
  }
  if (!kandidaten.length) return null;
  // Stabiel sorteren: gelijke afstand én gelijke annotatiestand houdt de
  // bronvolgorde, precies zoals vóór deze sleutel.
  kandidaten.sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]));
  return kandidaten[0][2];
}

// --- DEZELFDE KEUZE, MAAR ÉÉN KEER (de shape-INDEX) -------------------------
//
// `shapeForNode` berekent per aanroep de subklasse-sluiting van ELKE shape; met
// 60 shapes en 564 verwezen knopen zijn dat 33.840 fixpunten (gemeten: 334 ms op
// het domeincorpus). De affordance van 11 sep heeft per gedekte knoop meer nodig
// dan JA/NEE — zij wil het KERNGEGEVEN, en dat hangt aan de shape — dus is de
// dekkingstabel alleen niet genoeg.
//
// De index draait de vraag om: één sluiting per shape (60 in plaats van 33.840),
// en de uitkomst per KLASSE bewaard. Wat erin staat is precies de sorteersleutel
// van `shapeForNode`: de AFSTAND (0 = de doelklasse zelf, 1 = via subClassOf),
// daarna de ANNOTATIESTAND (een formulier-shape wint van een toetsshape), daarna
// de bronvolgorde. De opzoeking neemt over de rdf:types van de knoop het
// minimum van diezelfde sleutel — dus hetzelfde antwoord, en dat is als toets
// vastgelegd op het hele domeincorpus (`forms.test.mjs`).
export function shapeIndex(dataStore, shapes, fallbacks = []) {
  const overridden = new Set();
  for (const s of shapes) overridden.add(s.targetClass);
  const alle = [...shapes, ...fallbacks.filter((f) => !overridden.has(f.targetClass))];
  const index = new Map();
  alle.forEach((s, idx) => {
    const vorm = isForm(s) ? 0 : 1;
    const zet = (cls, rang) => {
      const oud = index.get(cls);
      if (!oud || rang < oud.rang || (rang === oud.rang && vorm < oud.vorm)) {
        index.set(cls, { rang, vorm, idx, shape: s });
      }
    };
    zet(s.targetClass, 0);
    for (const sub of subclassClosure(dataStore, s.targetClass)) {
      if (sub !== s.targetClass) zet(sub, 1);
    }
  });
  return index;
}

/** De shape van deze knoop volgens de index. Zelfde antwoord als
 *  `shapeForNode`, zonder de sluiting opnieuw te berekenen. */
export function shapeForNodeIndexed(dataStore, termOrIri, index) {
  if (!index || !index.size) return null;
  const term = typeof termOrIri === 'string' ? namedNode(termOrIri) : termOrIri;
  if (!term) return null;
  let beste = null;
  for (const q of dataStore.getQuads(term, namedNode(RDF + 'type'), null, null)) {
    if (q.object.termType !== 'NamedNode') continue;
    const kand = index.get(q.object.value);
    if (!kand) continue;
    if (!beste || kand.rang < beste.rang
      || (kand.rang === beste.rang && kand.vorm < beste.vorm)
      || (kand.rang === beste.rang && kand.vorm === beste.vorm && kand.idx < beste.idx)) {
      beste = kand;
    }
  }
  return beste ? beste.shape : null;
}

/** HET KERNGEGEVEN (dash:KeyInfoRole) van één knoop — wat naast zijn naam hoort
 *  te staan, zonder het hele formulier te bouwen.
 *
 *  Dezelfde keuze als in `formModel`: de KeyInfoRole-properties op sh:order, en
 *  de EERSTE die waarden oplevert wint. Geen waarden, geen kerngegeven — de
 *  aanroeper zet dan geen lege badge neer. */
export function keyInfoFor(dataStore, termOrIri, shape) {
  if (!shape) return [];
  const term = typeof termOrIri === 'string' ? namedNode(termOrIri) : termOrIri;
  if (!term) return [];
  return shape.properties
    .filter((ps) => ps.role === 'KeyInfoRole')
    .sort((a, b) => (a.order ?? Infinity) - (b.order ?? Infinity))
    .map((ps) => itemsFor(dataStore, term, ps))
    .find((items) => items.length) || [];
}

/** HET TYPE VAN EEN GEDEKTE KNOOP — de tekst voor de type-pil op een vouwkop
 *  (eigenaarswens 14 sep 2026: "Is het mogelijk om de uitklap forms ook iets
 *  meer dezelfde look als de high-level chips te geven?").
 *
 *  DE NAAM KOMT VAN DE DOELKLASSE, NIET VAN DE SHAPE, en dat is één plek en
 *  geen twee. Een shape is een KIJK op een klasse en heet daar ook naar: de
 *  formulier-shapes van een domeinprofiel dragen `rdfs:label "GLS-formulier"`,
 *  "Rol-formulier", "Componentformulier" — dat is de naam van het FORMULIER.
 *  De pil wil de naam van het DING: `gd:Gegevensleveringsspecificatie`
 *  heet "Gegevensleveringsspecificatie", en dat staat op de klasse. Bijkomend
 *  voordeel van dezelfde keuze: de klasse is een `skos:Concept` in het
 *  profielvocabulaire, dus haar afkorting hoort daar per SKOS al thuis.
 *
 *  DE AFKORTING IS `skos:altLabel` OP DIE KLASSE, en zij WINT van de volle
 *  naam. De eigenaarswens noemt haar zelf ("Misschien dat we óók nog een
 *  abbreviation moeten ondersteunen"), en zij bestond in
 *  `data/vlierdam/glo-vocabulaire.ttl` al vóór deze ronde: GLO,
 *  GLS, LGM, TGM. Een profiel dat geen afkorting opschrijft krijgt de volle
 *  naam; een viewer zonder profielvocabulaire krijgt de localName van de
 *  klasse via `labelFor`, en dat is nog steeds een typenaam en geen IRI-staart.
 *
 *  TWEE VELDEN, want de weergave heeft ze allebei nodig: `text` is wat in de
 *  pil komt, `vol` de volle naam voor het title-attribuut — een afkorting die
 *  nergens uitgeschreven staat is een raadsel in plaats van een label.
 *
 *  De DATA-graaf gaat voor: profielvocabulaire (profiel.ttl) staat daar, en een
 *  meegeleverde shape draagt zijn eigen store als terugval. */
export function typeLabelFor(dataStore, shape) {
  if (!shape || !shape.targetClass) return null;
  const cls = namedNode(shape.targetClass);
  const stores = shape.store && shape.store !== dataStore
    ? [dataStore, shape.store] : [dataStore];
  const kies = (pred) => {
    for (const s of stores) {
      const v = pickLabel(objs(s, cls, pred).filter(isLiteral));
      if (v) return v;
    }
    return null;
  };
  const alt = kies(SKOS + 'altLabel');
  const vol = kies(RDFS + 'label') || kies(SKOS + 'prefLabel')
    || kies('http://purl.org/dc/terms/title') || localName(shape.targetClass);
  if (!vol) return null;
  return { text: alt || vol, vol, afgekort: !!alt };
}

// --- IS DEZE KNOOP GEDEKT? --------------------------------------------------
//
// De vraag die de UITKLAP-affordance stelt, en zij wordt heel vaak gesteld:
// elke verwezen knoop in elke rij van elke kaart wil weten of er een formulier
// achter zit. `shapeForNode` is daar het verkeerde gereedschap voor — die doet
// per shape een eigen subklasse-fixpunt over de hele graaf, en levert een
// antwoord (WELKE shape) waar alleen een JA/NEE nodig is.
//
// Vandaar deze twee: één DEKKINGSTABEL — de doelklassen van alle shapes, met de
// subklasse-sluiting er in één fixpunt omheen — en een opzoeking die verder
// niets doet dan de rdf:types van de knoop erin zoeken. De aanroeper bewaart de
// tabel zolang de graaf niet verandert.
//
// GEMETEN op het toenmalige domeincorpus (6 bronnen, 4.899 quads, 60 shapes,
// 564 verwezen IRI's — de bovengrens van wat één documentopbouw aan
// dekkingsvragen stelt):
//   `shapeForNode` per vraag   334,0 ms
//   dekkingstabel                1,5 ms   (het bouwen van de tabel inbegrepen)
// Ter vergelijking kost één OPEN vouw — het GLS-formulier, met al zijn waarden
// en groepen — 1,33 ms. De affordance is dus goedkoper dan het ding waartoe zij
// toegang geeft, en dát is de voorwaarde om hem overal neer te zetten.
//
// ALLEEN FORMULIER-SHAPES TELLEN MEE (zie `isFormShape`). Een shape die alleen
// constraints draagt zegt niets over weergave, en met haar zou elke
// `odrl:Permission` in een domeinprofiel "gedekt" heten — het profiel toetst die
// klasse namelijk (`DoelgebondenPermissionShape`) zonder er een formulier voor
// te schrijven. Een uitklap op elke regelverwijzing is precies de ruis die de
// eigenaar niet vroeg; de affordance hoort te verschijnen waar een profiel
// AUTEUR een kaart heeft opgeschreven.
export function coveredClasses(dataStore, shapes) {
  const klassen = new Set();
  for (const s of shapes) if (isFormShape(s)) klassen.add(s.targetClass);
  if (!klassen.size) return klassen;
  const subklassen = dataStore.getQuads(null, namedNode(RDFS + 'subClassOf'), null, null);
  let changed = true;
  while (changed) {
    changed = false;
    for (const q of subklassen) {
      if (klassen.has(q.object.value) && !klassen.has(q.subject.value)) {
        klassen.add(q.subject.value);
        changed = true;
      }
    }
  }
  return klassen;
}

/** Draagt deze knoop een rdf:type dat door de dekkingstabel gedekt wordt? */
export function isCovered(dataStore, termOrIri, klassen) {
  if (!klassen || !klassen.size) return false;
  const term = typeof termOrIri === 'string' ? namedNode(termOrIri) : termOrIri;
  if (!term) return false;
  return dataStore.getQuads(term, namedNode(RDF + 'type'), null, null)
    .some((q) => q.object.termType === 'NamedNode' && klassen.has(q.object.value));
}

/** WELKE knopen in de graaf zijn gedekt — de verzameling waarvan `countCovered`
 *  hieronder alleen de grootte teruggeeft.
 *
 *  De twee soorten staan APART: `iris` zijn de gedekte IRI-knopen, `blanks` is
 *  het aantal gedekte blanke knopen. Dat onderscheid is er voor de aanroeper die
 *  de lijst over de lijn wil sturen — de unie-telling in `stores/corpus.ts`
 *  stuurt de IRI's als uitsluiting een SPARQL-query in, en een blanke knoop
 *  heeft daar geen naam om mee te noemen. Voor de TELLING maakt het niets uit:
 *  beide soorten tellen, precies zoals voorheen.
 *
 *  `skipGraphs` laat quads uit die named graphs buiten beschouwing. Dat is wat
 *  de GEMENGDE bronstand nodig heeft: daar staat het endpointmateriaal in de
 *  graph van het endpoint en groeit het terwijl de lezer klikt, dus een telling
 *  die de BESTANDSkant wil kennen moet die graph kunnen overslaan. */
export function coveredNodes(dataStore, klassen, { skipGraphs } = {}) {
  const iris = new Set();
  const blanken = new Set();
  if (!klassen || !klassen.size) return { iris, blanks: 0 };
  const over = skipGraphs && skipGraphs.length ? new Set(skipGraphs) : null;
  for (const q of dataStore.getQuads(null, namedNode(RDF + 'type'), null, null)) {
    if (q.object.termType !== 'NamedNode' || !klassen.has(q.object.value)) continue;
    if (over && q.graph && over.has(q.graph.value)) continue;
    (q.subject.termType === 'NamedNode' ? iris : blanken).add(q.subject.value);
  }
  return { iris, blanks: blanken.size };
}

/** Hoeveel knopen in de graaf zijn gedekt? De telling van de statusregel. */
export function countCovered(dataStore, klassen) {
  const uit = coveredNodes(dataStore, klassen);
  return uit.iris.size + uit.blanks;
}

// --- Waarden ophalen --------------------------------------------------------
function valuesFor(dataStore, term, ps) {
  if (!ps.path) return [];
  return ps.inverse
    ? dataStore.getQuads(null, namedNode(ps.path), term, null).map((q) => q.subject)
    : dataStore.getQuads(term, namedNode(ps.path), null, null).map((q) => q.object);
}

// Het label van een veld: sh:name in de actieve taal, anders het label van het
// predicaat zelf (SHUI §Label Resolution), anders de localName.
function propLabel(dataStore, ps) {
  const named = pickLabel(ps.names);
  if (named) return named;
  if (ps.path) return labelFor(dataStore, namedNode(ps.path));
  return '';
}

// De UITLEG bij een veld — spiegelbeeld van propLabel. sh:description is de
// uitleg die de SHAPE geeft: zij is voor dít formulier geschreven en gaat dus
// vóór de algemene definitie van het pad-predicaat (note §1). Ontbreekt zij,
// dan valt de rij terug op wat het vocabulaire over het predicaat zegt —
// dezelfde route als de label-resolutie hierboven.
function propDescription(dataStore, ps) {
  return pickLabel(ps.descriptions)
    || (ps.path ? descriptionFor(dataStore, namedNode(ps.path)) : '')
    || null;
}

// Wijst deze IRI BUITEN het geladen corpus? Dat is de vraag of de knoop hier
// beschreven wordt: staat hij als SUBJECT in de store, dan leeft hij in de
// data en heeft de weergave er zelf al een plek voor. Staat hij er niet, dan is
// de IRI alles wat we van hem hebben en mag hij als verwijzing naar buiten
// gelezen worden.
//
// Deze vraag hoort HIER en niet in de weergave: het is een uitspraak over de
// GRAAF, geen presentatiekeuze. Wat de weergave er vervolgens mee doet — er een
// anker van maken, en alleen voor schema's die een browser kan volgen — blijft
// aan doc.js.
function pointsOutside(dataStore, term) {
  if (!term || term.termType !== 'NamedNode') return false;
  return dataStore.countQuads(term, null, null, null) === 0;
}

// Eén waarde als weergave-item. `kind` zegt hoe doc.js hem tekent:
//   text  — letterlijk (dash:LiteralViewer)
//   link  — de IRI zelf, als link (dash:URIViewer / shui:IRIViewer)
//   label — het label van de doelknoop (dash:LabelViewer), met de IRI erbij
//           zodat een weergave er desgewenst naartoe kan springen
//
// LABEL ALS HYPERLINK. DASH omschrijft dash:LabelViewer als "a hyperlink to
// that URI based on the display label of the resource" — linktekst het label,
// bestemming de IRI. Dat geldt alléén voor een knoop die hier niet beschreven
// wordt: interne IRI's staan in deze viewer nergens als naakte link, want
// daarvoor is de weergave zelf de plek. Het item draagt daarom `external`; de
// tekst blijft in beide gevallen het label.
function valueItem(dataStore, term, ps) {
  const labelItem = () => ({
    kind: 'label',
    text: labelFor(dataStore, term),
    iri: term.termType === 'NamedNode' ? term.value : null,
    external: pointsOutside(dataStore, term),
  });
  switch (ps.viewer) {
    case 'URIViewer':
    case 'HyperlinkViewer':
      return { kind: 'link', text: term.value, iri: term.termType === 'NamedNode' ? term.value : null };
    case 'LabelViewer':
      return labelItem();
    case 'LiteralViewer':
      return { kind: 'text', text: term.value, iri: null };
    default:
      // Geen widget aangewezen: een IRI leest als label, een literal letterlijk.
      return term.termType === 'NamedNode'
        ? labelItem()
        : { kind: 'text', text: term.value, iri: null };
  }
}

// De waarden van één property, al gekozen en al ontdubbeld.
//
// TAALRESOLUTIE (SHUI §Label and Language Resolution, en het taalregime dat de
// rest van deze viewer al aanhoudt): meerdere literals met een taalmarkering
// zijn vertalingen van elkaar, geen aparte waarden — er blijft er ÉÉN over, die
// het best bij de voorkeurstaal past (met terugval langs de TAALVOORKEUR-keten,
// daarna de resttalen en als laatste een taal-loze literal). Literals
// zonder taalmarkering en IRI's blijven allemaal staan. dash:LangStringViewer
// zegt dit expliciet; zonder die widget geldt hetzelfde, want twee talen naast
// elkaar tonen is nooit de bedoeling.
function itemsFor(dataStore, term, ps) {
  const values = valuesFor(dataStore, term, ps);
  if (!values.length) return [];
  const getagd = values.filter((v) => isLiteral(v) && v.language);
  if (getagd.length) {
    const one = pickLabel(getagd);
    const rest = values.filter((v) => !(isLiteral(v) && v.language));
    return [
      ...(one ? [{ kind: 'text', text: one, iri: null }] : []),
      ...rest.map((v) => valueItem(dataStore, v, ps)),
    ];
  }
  if (ps.viewer === 'LangStringViewer') {
    const one = pickLabel(values.filter(isLiteral));
    return one ? [{ kind: 'text', text: one, iri: null }] : [];
  }
  const out = [];
  const seen = new Set();
  for (const v of values) {
    const item = valueItem(dataStore, v, ps);
    const key = item.kind + '\u0000' + item.text;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

// --- Het formuliermodel -----------------------------------------------------
//
// { title, keyInfo: [item], description, blocks: [ group | row ] }
//   group = { kind: 'group', label, rows: [row] }
//   row   = { kind: 'row', label, description, path, inverse, pattern, viewer,
//             values: [item] }
//
// Lege properties komen er niet in: een viewer laat weg wat niet in de data
// staat (net als het handgeschreven formulier deed). Een groep zonder gevulde
// rijen verdwijnt in haar geheel.
export function formModel(dataStore, termOrIri, shape) {
  const term = typeof termOrIri === 'string' ? namedNode(termOrIri) : termOrIri;
  const roleItems = (role) => shape.properties
    .filter((ps) => ps.role === role)
    .sort((a, b) => (a.order ?? Infinity) - (b.order ?? Infinity))
    .map((ps) => itemsFor(dataStore, term, ps))
    .find((items) => items.length) || [];

  const titleItems = roleItems('LabelRole');
  const descItems = roleItems('DescriptionRole');
  const titel = titleItems.length ? titleItems[0].text : labelFor(dataStore, term);

  // DE TITEL STAAT ER ÉÉN KEER (opruimpunt 30).
  //
  // Wijst de shape geen dash:LabelRole aan, dan valt de kop terug op de eigen
  // naam-literal van de knoop — rdfs:label, skos:prefLabel of dct:title, in die
  // volgorde (labelFor/ownLabel in parse.js). Draagt diezelfde shape dat
  // predicaat óók als gewone property, dan stond dezelfde tekst twee keer in het
  // formulier: als kop én als veld. Gemeten op de validatieshape `GlsShape`
  // — "GLS detentie-einde-berichten Vlierdam" als titel én als rij `title`.
  //
  // De toets is EENWAARDIG en LETTERLIJK: alleen een rij die precies de titel
  // herhaalt verdwijnt. Draagt het naam-predicaat meer dan één waarde, dan toont
  // de kop er één en zegt de rij iets wat de kop niet zegt — dan blijft zij
  // staan. Er verdwijnt zo nooit stilzwijgend een waarde uit de weergave.
  const NAAM_PREDS = new Set([
    RDFS + 'label',
    'http://www.w3.org/2004/02/skos/core#prefLabel',
    'http://purl.org/dc/terms/title',
  ]);
  const herhaaltDeKop = (ps, items) => !titleItems.length && !ps.inverse
    && NAAM_PREDS.has(ps.path) && items.length === 1 && items[0].text === titel;

  const shapeStore = shape.store || dataStore;
  const groups = new Map();
  const seq = [];
  for (const ps of shape.properties) {
    if (ps.role === 'LabelRole' || ps.role === 'DescriptionRole' || ps.role === 'KeyInfoRole') continue;
    if (!ps.path) continue;
    const waarden = itemsFor(dataStore, term, ps);
    if (herhaaltDeKop(ps, waarden)) continue;
    const row = {
      kind: 'row',
      label: propLabel(dataStore, ps),
      description: propDescription(dataStore, ps),
      // HET PAD VAN DEZE RIJ, in dezelfde twee delen als de shape het opschrijft:
      // het predicaat, en de RICHTING waarin het gelezen is. Zonder deze twee
      // zou een weergave die de rij bewerkbaar maakt het predicaat opnieuw uit
      // de shape moeten terugvissen — precies de domeinkennis die dit bestand
      // juist wél al gelezen heeft.
      //
      // `inverse` is geen detail: bij een [ sh:inversePath p ] hangt de getoonde
      // waarde aan (waarde, p, deze knoop) en NIET aan (deze knoop, p, waarde).
      // Wie dat verschil negeert en op `path` schrijft, laat de getoonde waarde
      // staan en zet er een verzonnen triple in de andere richting naast. Dit
      // bestand oordeelt niet over bewerkbaarheid — het zegt alleen eerlijk hoe
      // de waarde eraan hangt.
      path: ps.path,
      inverse: ps.inverse,
      pattern: ps.pattern,
      viewer: ps.viewer,
      values: waarden,
      order: ps.order,
    };
    if (ps.group) {
      let g = groups.get(ps.group);
      if (!g) {
        const gOrder = obj(shapeStore, namedNode(ps.group), SH + 'order');
        g = {
          kind: 'group',
          label: labelFor(shapeStore, namedNode(ps.group)),
          rows: [],
          order: gOrder && Number.isFinite(parseFloat(gOrder.value)) ? parseFloat(gOrder.value) : null,
        };
        groups.set(ps.group, g);
        seq.push(g);
      }
      g.rows.push(row);
    } else {
      seq.push(row);
    }
  }
  // Stabiel sorteren op order; zonder order achteraan, in bronvolgorde.
  const byOrder = (list) => list
    .map((x, i) => [x, i])
    .sort((a, b) => ((a[0].order ?? Infinity) - (b[0].order ?? Infinity)) || (a[1] - b[1]))
    .map(([x]) => x);
  for (const g of groups.values()) g.rows = byOrder(g.rows).filter((r) => r.values.length);
  const blocks = byOrder(seq)
    .filter((b) => (b.kind === 'group' ? b.rows.length : b.values.length));

  return {
    shape: shape.iri,
    title: titel,
    keyInfo: roleItems('KeyInfoRole'),
    description: descItems.length ? descItems[0].text : null,
    blocks,
  };
}

/** HET FORMULIER ZONDER DE TERUGVERWIJZING NAAR DE KNOOP WAARONDER HET HANGT
 *  (eigenaarsmelding 14 sep 2026: "Je hebt nu in de formulieren vaak een
 *  'Samenhang' sectie die terugverwijst naar de parent waarvandaan je
 *  uitgeklapt bent... het is nu onnodige dubbeling van informatie.").
 *
 *  De lezer klapt de GLS open, daarin het logisch gegevensmodel, en het LGM
 *  zegt onder «Samenhang → Gebruikt door» netjes: de GLS. Dat is waar, maar hij
 *  staat twee regels hoger als de kop waar de lezer zojuist op klikte; de rij
 *  voegt niets toe en de groepskop eromheen kost een blok.
 *
 *  ALLEEN DE DIRECTE OUDER, en dat is een afweging en geen gemak. Een
 *  verwijzing naar een VERDERE voorouder zegt wél iets: zij maakt zichtbaar dat
 *  twee takken op hetzelfde uitkomen, en de cyclusrem in de weergave toont haar
 *  al zonder vouw (een kale verwijzing, geen tweede kaart). De dubbeling die de
 *  melding noemt is precies de directe ouder — de knoop die letterlijk boven
 *  dit formulier in beeld staat.
 *
 *  LEEG IS WEG, op beide niveaus: een rij die al haar waarden verliest
 *  verdwijnt, en een groep die al haar rijen verliest verdwijnt met kop en al —
 *  dezelfde regel die `formModel` hierboven al voor lege properties hanteert
 *  ("een viewer laat weg wat niet in de data staat").
 *
 *  DE TITEL, HET KERNGEGEVEN EN DE BESCHRIJVING BLIJVEN. Die gaan over de
 *  knoop zelf en niet over zijn omgeving; ze kunnen per constructie niet de
 *  dubbeling zijn waar de melding over gaat.
 *
 *  PUUR, en een NIEUW model: de aanroeper mag het oorspronkelijke model
 *  bewaren (`formModel` cachet niet, maar een weergave die dat wel doet mag er
 *  niet door veranderen). Zonder ouder — een formulier op het TOPniveau, direct
 *  op een kaartrij — komt het model onveranderd terug. */
export function dropBacklinks(model, parentIri) {
  if (!model || !parentIri) return model;
  const houd = (v) => v.iri !== parentIri;
  const rij = (r) => {
    const values = r.values.filter(houd);
    return values.length === r.values.length ? r : { ...r, values };
  };
  const blocks = [];
  let veranderd = false;
  for (const b of model.blocks) {
    if (b.kind === 'group') {
      const rows = b.rows.map(rij).filter((r) => r.values.length);
      const zelfde = rows.length === b.rows.length && rows.every((r, i) => r === b.rows[i]);
      if (!zelfde) veranderd = true;
      if (rows.length) blocks.push(zelfde ? b : { ...b, rows });
      continue;
    }
    const r = rij(b);
    if (r !== b) veranderd = true;
    if (r.values.length) blocks.push(r);
  }
  if (!veranderd) return model;
  return { ...model, blocks };
}

// --- De meegeleverde shapes -------------------------------------------------
// Eén keer parsen, daarna hergebruiken. Zelfde rol als de meegeleverde
// ODRL-labelbundel: er is altijd een formulier, ook als geen enkele bron er een
// meebrengt — en een shape uit de data wint (zie shapeForNode).
let builtinCache = null;
export function builtinShapes(ttlSources) {
  if (builtinCache) return builtinCache;
  const store = new Store();
  for (const ttl of ttlSources) {
    store.addQuads(new Parser().parse(ttl));
  }
  builtinCache = readShapes(store);
  return builtinCache;
}
