// De WEERGAVESTATE, gesynchroniseerd met de adresbalk.
//
// Eén bron van waarheid voor alles wat de lezer aan de weergave kan veranderen
// en wat deelbaar hoort te zijn. De parameternamen zijn LETTERLIJK die van de
// bevroren viewer (viewer-bevroren/assets/doc.js, blok "Boot: URL-parameters identiek
// aan de viewer" plus de losse *FromUrl/*ToUrl-functies): elke bestaande
// gedeelde link moet in de nieuwe app hetzelfde beeld opleveren.
//
//   ?src=<url>            GENERIEKE bron, herhaalbaar, volgorde behouden
//   ?ttl=<url>            legacy-alias van ?src (telt altijd als bestand)
//   ?sparql=<url>         legacy-alias van ?src voor een endpoint
//   ?policy=<IRI>         beperk de weergave tot deze policy
//   ?set=<IRI>            de leden van één beleidspublicatie
//   ?groupby=<curie>,…    actieve groeperingsdimensies in nestvolgorde;
//                         afwezig = bronvolgorde (null), leeg = platte lijst
//   ?edit=1               start in de bewerk-stand (deeltraject 3)
//   ?exclude-graph=<IRI>  herhaalbaar; named graphs buiten detail-CONSTRUCTs
//   ?status=<a,b,c>       levenscyclusfilter van de kaartenlijst
//   ?aanbod=<IRI>         aanbodfilter van de Overeenkomsten-sectie
//   ?lang=nl|en           taal van de weergave (default nl)
//
// Schrijven gaat via history.replaceState: de adresbalk volgt de weergave, maar
// een terugknop hoort de lezer naar de vorige PAGINA te brengen, niet door zijn
// filterkeuzes heen. Dat is het patroon van langToUrl/filterToUrl/groupByToUrl
// in de oude viewer. Deze module is daarmee de ENE schrijver van de adresbalk.
//
// `?verken=<IRI>` STOND HIER TOT 16 SEP 2026 en zette de verkenner-stand; hij
// was de enige parameter met een pushState-uitzondering (verken-history.ts),
// zodat browser-terug tussen document en verkenner liep. De verkenner is
// gesloopt (eigenaarsbesluit: "Comunica gebruik ik praktisch nooit. Mag weg
// incl functionaliteit in de viewer/editor"), en daarmee ook die uitzondering:
// er is nu geen enkele weergavekeuze meer die een geschiedenisstap maakt.
// Een oude `?verken=`-deeplink is sindsdien een VREEMDE parameter zoals
// `utm_*` — hij wordt niet gelezen, hij crasht niets, de lezer krijgt de gewone
// documentweergave, en hij blijft ongemoeid in de adresbalk staan.
//
// De synchronisatie is TOTAAL: `naarUrl()` schrijft de HELE store uit, zodat
// store en adresbalk per constructie niet uit elkaar kunnen lopen. Parameters
// van buiten (utm_*, wat dan ook) blijven staan — alleen de elf eigen namen
// worden herschreven.
import { createSignal } from 'solid-js';
import { createStore } from 'solid-js/store';
import { getLang, normalizeLang, setLang } from '../model/i18n.js';
import { t } from '../model-grens.js';

export type Stand = 'doc' | 'sparql';
export type Taal = 'nl' | 'en';
export type Levenscyclus = 'active' | 'terminated' | 'future';

// Vaste volgorde; ook de volgorde waarin ?status= wordt uitgeschreven.
export const LEVENSCYCLI: Levenscyclus[] = ['active', 'terminated', 'future'];

export interface Filters {
  /** null = geen keuze (alles); anders de aangevinkte levenscycli. */
  status: Levenscyclus[] | null;
  /** '' = geen aanbodfilter. */
  aanbod: string;
}

export interface Weergave {
  stand: Stand;
  src: string[];
  ttl: string[];
  sparql: string | null;
  policyScope: string | null;
  setScope: string | null;
  /** null = bronvolgorde (sh:order); [] = platte lijst. */
  groupBy: string[] | null;
  lang: Taal;
  /** Stond `?lang=` in de URL, of is de taalkiezer gebruikt? Dan (en alleen
   *  dan) draagt de adresbalk de taal — zoals in de oude viewer, waar alleen
   *  langToUrl hem schrijft. */
  langExpliciet: boolean;
  editMode: boolean;
  excludeGraphs: string[];
  filters: Filters;
}

function leeg(): Weergave {
  return {
    stand: 'doc',
    src: [], ttl: [], sparql: null,
    policyScope: null, setScope: null,
    groupBy: null,
    lang: 'nl',
    langExpliciet: false,
    editMode: false,
    excludeGraphs: [],
    filters: { status: null, aanbod: '' },
  };
}

const [weergave, setWeergave] = createStore<Weergave>(leeg());
export { weergave };

/** De taal reactief lezen én vertalen: elke component die tekst toont roept
 *  dit aan in plaats van t(), zodat een taalwissel hem opnieuw laat lopen.
 *  De stringtabel zelf blijft in de framework-vrije modellaag (i18n.js). */
export function tekst(sleutel: string, vars?: Record<string, unknown>): string {
  void weergave.lang;                  // reactieve afhankelijkheid, bewust
  return t(sleutel, vars);
}

function statusUitUrl(raw: string | null): Levenscyclus[] | null {
  if (!raw) return null;
  const want = raw.split(',').map((s) => s.trim())
    .filter((s): s is Levenscyclus => (LEVENSCYCLI as string[]).includes(s));
  return want.length ? want : null;
}

/** Vul de store uit een zoekstring (`location.search`). Schrijft NIET terug:
 *  een binnenkomende link blijft staan zoals hij is, legacy-aliassen incluis. */
export function leesUitUrl(search: string): void {
  const p = new URLSearchParams(search);
  const lang = normalizeLang(p.get('lang')) as Taal;
  // De modellaag leest dezelfde instelling voor haar labelvoorkeur (parse.js),
  // dus meteen zetten — vóór de eerste render, net als in doc.js.
  setLang(lang);
  setWeergave({
    ...leeg(),
    stand: 'doc',
    src: p.getAll('src'),
    ttl: p.getAll('ttl'),
    sparql: p.get('sparql') || null,
    policyScope: p.get('policy') || null,
    setScope: p.get('set') || null,
    groupBy: p.has('groupby')
      ? String(p.get('groupby') || '').split(',').map((s) => s.trim()).filter(Boolean)
      : null,
    lang,
    langExpliciet: p.has('lang'),
    editMode: p.get('edit') === '1',
    excludeGraphs: p.getAll('exclude-graph'),
    filters: { status: statusUitUrl(p.get('status')), aanbod: p.get('aanbod') || '' },
  });
}

// De elf namen die deze store bezit. Alles wat hier NIET in staat is een
// parameter van buiten (utm_*, een oude `?verken=`, wat dan ook) en blijft
// ongemoeid.
const URL_SLEUTELS = ['src', 'ttl', 'sparql', 'policy', 'set', 'groupby',
  'edit', 'exclude-graph', 'status', 'aanbod', 'lang'] as const;

/** Store -> zoekstring. TOTAAL: elke sleutel met een URL-afbeelding wordt hier
 *  geschreven, dus er is geen pad waarlangs de store en de adresbalk uit elkaar
 *  kunnen lopen. `stand` is de enige URL-loze sleutel: hij is afgeleid —
 *  'sparql' hangt aan de brondetectie (taak 8), anders 'doc'. */
export function naarUrl(w: Weergave, basis?: URLSearchParams): URLSearchParams {
  const u = new URLSearchParams(basis);
  for (const k of URL_SLEUTELS) u.delete(k);
  for (const s of w.src) u.append('src', s);
  for (const s of w.ttl) u.append('ttl', s);
  if (w.sparql) u.set('sparql', w.sparql);
  // De twee scopes sluiten elkaar uit (wirePolicySelect in de oude viewer);
  // zetWeergave bewaakt dat, hier volgt de URL simpelweg de store.
  if (w.policyScope) u.set('policy', w.policyScope);
  if (w.setScope) u.set('set', w.setScope);
  // Drie standen: afwezig (bronvolgorde), leeg (platte lijst), lijst.
  if (w.groupBy) u.set('groupby', w.groupBy.join(','));
  if (w.editMode) u.set('edit', '1');
  for (const g of w.excludeGraphs) u.append('exclude-graph', g);
  if (w.filters.status) {
    u.set('status', LEVENSCYCLI.filter((s) => w.filters.status!.includes(s)).join(','));
  }
  if (w.filters.aanbod) u.set('aanbod', w.filters.aanbod);
  // ?lang= verschijnt pas zodra de taal EXPLICIET gekozen is (uit de URL of via
  // de taalkiezer) — precies als in de oude viewer, waar alleen langToUrl hem
  // schrijft. Anders zou elke filterklik ongevraagd &lang=nl aanplakken.
  if (w.langExpliciet) u.set('lang', w.lang);
  return u;
}

function schrijfUrl(w: Weergave): void {
  if (typeof history === 'undefined' || !history.replaceState) return;
  const q = naarUrl(w, new URLSearchParams(location.search)).toString();
  history.replaceState(null, '', q ? '?' + q : location.pathname);
}

/** Weergavekeuze wijzigen: de patch gaat de store in, waarna de HELE store naar
 *  de adresbalk wordt geschreven. Sleutels die niet in de patch zitten blijven
 *  dus staan — in de store én in de URL. */
export function zetWeergave(patch: Partial<Weergave>): void {
  const volgend: Partial<Weergave> = { ...patch };

  if ('lang' in volgend && volgend.lang) {
    const next = normalizeLang(volgend.lang) as Taal;
    // setLang vóór de storemutatie: die triggert de herrender, en die moet de
    // NIEUWE taal uit de stringtabel lezen.
    setLang(next);
    volgend.lang = next;
    // Ook `nl` wordt uitgeschreven: de taal is een expliciete keuze en een
    // gedeelde link hoort hem te dragen, ook als hij de default is.
    volgend.langExpliciet = true;
  }
  // Een scope ZETTEN sluit de andere uit; een scope leegmaken raakt de andere
  // niet (die staat los in de adresbalk en hoort daar te blijven).
  if (volgend.policyScope) volgend.setScope = null;
  else if (volgend.setScope) volgend.policyScope = null;
  // Alles aangevinkt is geen keuze: normaliseren naar null, dan is het
  // round-trip door de URL (waar de parameter dan verdwijnt) sluitend.
  if (volgend.filters && volgend.filters.status
      && volgend.filters.status.length === LEVENSCYCLI.length) {
    volgend.filters = { ...volgend.filters, status: null };
  }

  setWeergave(volgend as Weergave);
  schrijfUrl(weergave);
}

/** De actieve taal zoals de modellaag hem kent — handig in tests en asserts. */
export const huidigeTaal = getLang;

// --- DE SPRONG BINNEN DE PAGINA (revealInUi) --------------------------------
// Eén IRI aanwijzen in de weergave: vanuit de zijnav en vanuit een
// kruisverwijzing op een kaart. Een sprong is
// meer dan scrollen — het doel kan achter een dichte sectie zitten, buiten de
// getekende chunk vallen of door een filter verborgen zijn. De LIJST weet dat
// allemaal en de store niet, dus draait de verantwoordelijkheid om: elke sectie
// meldt zich hier aan met een ONTHULLER die zegt "die ken ik" en hem
// tevoorschijn haalt; deze module doet daarna de DOM-kant (het pad openklappen,
// scrollen, oplichten). Dat is dezelfde taakverdeling als
// revealInUi/state.revealSections in de bevroren viewer.

// --- De vluchtige melding op de statusregel ---------------------------------
// De bevroren viewer schrijft een mislukte sprong met `setStatus(...)` in de
// statusregel (doc.js r.963-967): niet elke boomknoop heeft een kaart, en
// zonder melding klikt de lezer in het niets. De statusregel van de nieuwe app
// leidt haar tekst af uit de CORPUSSTORE; een losse mededeling past daar niet
// in, dus staat zij hier — als i18n-SLEUTEL, niet als tekst, zodat een
// taalwissel haar meteen hertaalt.
// CONTRACTWIJZIGING (dt3, lane-bronnen-edit): de melding draagt nu ook zijn
// INVULWAARDEN. De bronnenlaag meldt dingen die zonder hun waarden niets zeggen
// ("Lokale kopie gemaakt van {bron}", "{n} onderdelen…"), en een tweede signaal
// ernaast zou de twee uit de pas kunnen laten lopen. `melding()` blijft de
// sleutel teruggeven, zodat elke bestaande lezer ongewijzigd blijft werken.
const [meldingStand, zetMeldingSignaal] =
  createSignal<{ sleutel: string; vars?: Record<string, unknown> } | null>(null);

/** De i18n-sleutel van de vluchtige melding, of null. */
export const melding = (): string | null => meldingStand()?.sleutel ?? null;
/** De invulwaarden die bij `melding()` horen. */
export const meldingVars = (): Record<string, unknown> | undefined => meldingStand()?.vars;

/** Zet (of wis met `null`) de vluchtige melding op de statusregel. */
export function zetMelding(sleutel: string | null, vars?: Record<string, unknown>): void {
  zetMeldingSignaal(sleutel ? { sleutel, vars } : null);
}

/** Haal de knoop met deze ref tevoorschijn. `true` = ik ken hem en heb er wat
 *  aan gedaan; de aanroeper hoeft geen andere onthuller meer te proberen. */
export type Onthuller = (ref: string) => boolean;

const onthullers = new Set<Onthuller>();

/** Meld een onthuller aan; de teruggegeven functie meldt hem weer af (in een
 *  component: `onCleanup(registreerOnthuller(...))`). */
export function registreerOnthuller(fn: Onthuller): () => void {
  onthullers.add(fn);
  return () => { onthullers.delete(fn); };
}

/** Laat de aangemelde onthullers deze ref tevoorschijn halen — sectie openen,
 *  zo nodig een filter wissen, de kaart laten bestaan — en verder NIETS: geen
 *  scroll, geen puls. `true` = een onthuller herkende hem.
 *
 *  Dit is de helft van `spring()` die een aanroeper met een eigen sprong nodig
 *  heeft. Het invulling-paneel is zo'n aanroeper: dat springt zelf, mét de
 *  voorrang van de kaart waar het paneel op staat (`kaartVanScope`), en heeft
 *  van de lijst alleen nodig dat de kaart er ís. */
export function onthul(ref: string): boolean {
  if (!ref) return false;
  for (const fn of [...onthullers]) {
    try { if (fn(ref)) return true; } catch { /* een stille onthuller blokkeert de rest niet */ }
  }
  return false;
}

/** Wachten tot Solid de DOM heeft bijgewerkt. Een onthuller zet SIGNALEN; de
 *  kaart die daaruit volgt bestaat pas na de volgende taak. */
const tik = (): Promise<void> => new Promise((r) => { setTimeout(r, 0); });

function zoekRef(ref: string): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  // Alleen " en \ hoeven te ontsnappen; de dubbele punten en schuine strepen
  // van een IRI zijn binnen een aangehaalde attribuutwaarde gewoon tekst.
  const veilig = ref.replace(/["\\]/g, '\\$&');
  return document.querySelector(`[data-ref="${veilig}"]`)
    || document.querySelector(`[data-iri="${veilig}"]`);
}

/** Scrollen mét controle achteraf. Een geanimeerde sprong over een lijst van
 *  1.392 kaarten haalt het niet altijd: op /brp-ap bleef de pagina meetbaar op
 *  scrollY 0 staan terwijl het doel op 65.728px stond — de kaarten worden op
 *  hetzelfde moment bijgetekend en de animatie sneuvelt in die herlayout. Dus:
 *  eerst de nette (eventueel geanimeerde) sprong, en als het doel na een halve
 *  seconde nog steeds buiten beeld staat alsnog hard erheen. Dat is dezelfde
 *  redenering als settleScrollAnchor in de bevroren viewer: kijken waar het
 *  doel echt terechtkwam en bijsturen, niet hopen. */
async function scrolNaar(doel: HTMLElement, smooth: boolean): Promise<void> {
  if (typeof doel.scrollIntoView !== 'function') return;
  doel.scrollIntoView({ behavior: smooth ? 'smooth' : 'auto', block: 'start' });
  for (let i = 0; i < 12; i += 1) {
    await new Promise((r) => { setTimeout(r, 40); });
    const top = doel.getBoundingClientRect().top;
    const hoogte = typeof window !== 'undefined' ? window.innerHeight : 0;
    if (top >= -4 && top < Math.max(hoogte, 1)) return;   // in beeld: klaar
  }
  doel.scrollIntoView({ behavior: 'auto', block: 'start' });
}

/** Springen naar een knoop in de weergave: sectie openen, de kaart laten
 *  bestaan, ernaartoe scrollen en hem kort laten oplichten. `false` = niet in
 *  de weergave te vinden (de aanroeper meldt dat zelf; niet elke boomknoop
 *  heeft een kaart). */
export async function spring(ref: string, opties: { smooth?: boolean } = {}): Promise<boolean> {
  if (!ref) return false;
  // Er is geen stand meer waarin de documentweergave ontbreekt: de
  // verkenner-stand is op 16 sep 2026 gesloopt. Hier stond zijn terugweg
  // ("eerst terug naar 'doc', anders landt de sprong op een niet-bestaande
  // kaart"); de SPARQL-stand is een schil ROND diezelfde documentweergave en
  // heeft die terugweg niet nodig.
  for (const fn of [...onthullers]) {
    try { if (fn(ref)) break; } catch { /* een stille onthuller blokkeert de rest niet */ }
  }
  await tik();
  const doel = zoekRef(ref);
  if (!doel) return false;
  // Het PAD openklappen: een regelrij zit in een kaart, die in een sectie.
  for (let n: HTMLElement | null = doel; n; n = n.parentElement) {
    if (n instanceof HTMLDetailsElement) n.open = true;
  }
  await scrolNaar(doel, !!opties.smooth);
  if (doel.classList) {
    doel.classList.remove('ui-flash');
    void doel.offsetWidth;                 // reflow, zodat de animatie herstart
    doel.classList.add('ui-flash');
    setTimeout(() => doel.classList.remove('ui-flash'), 1800);
  }
  return true;
}
