/** Eén bron zoals de modellaag hem verwacht. */
export interface Bron {
  name: string;
  url?: string;
  content: string;
  format: string;
  /** Komt deze bron uit het endpoint zelf (lijstskelet, detail- of
   *  knoop-CONSTRUCT)? Zulke pseudobronnen hebben geen eigen adres: de
   *  verkenner-link laat ze weg, en een her-ingest neemt ze mee terug. */
  fromSparql?: boolean;
  /** CONTRACTWIJZIGING (dt3, lane-bronnen-edit). Komt de inhoud van deze bron
   *  uit een lokale OPFS-kopie in deze browser? De bronnenlaag zet het erop
   *  (metOpfsBronnen); de bronnenbalk toont het als "(lokaal bewerkt)". De
   *  modellaag doet er niets mee — hij staat hier omdat de bron zelf hem
   *  meedraagt door het laadpad heen. */
  lokaal?: boolean;
}

/** EEN BRON- OF PARSEFOUT, in de vorm waarin hij ECHT gestempeld wordt.
 *
 *  De twee stempelaars leverden verschillende velden en dit type kende alleen
 *  `url` — dus las elke lezer `name` met een cast (`legeLijstMelding` in
 *  `ui/lijst/secties.tsx` deed dat met een noot erbij, en die noot vroeg om
 *  precies deze reparatie). De vorm is nu eerlijk:
 *
 *    * `name`  — de naam waaronder de bron in de lijst staat (`loadSources`);
 *    * `url`   — het adres, als de bron er een heeft (de laadschil, en sinds
 *                golf 3 ook `loadSources` zelf);
 *    * `regel` — het regelnummer uit de parser, als hij er een noemde. Het
 *                stond tot golf 3 als Engelse staart IN de boodschap ("… on
 *                line 10."); het is nu een gegeven, zodat de weergave er
 *                `bestand:regel` van kan maken zonder de zin te ontleden.
 *
 *  Minstens één van `name`/`url` is gevuld; welke, hangt van de stempelaar af,
 *  en daarom leest de weergave ze allebei. */
export interface Fout { name?: string; url?: string; message: string; regel?: number }

/** Het stuk van het weergavemodel dat de app-schil zelf leest; de rest wordt
 *  getypeerd zodra de componenten die het lezen bestaan (taak 3 e.v.). */
/** Het gedeelde kopje van een policy (Set/Offer/Agreement/Request): genoeg voor
 *  de schil, niet meer. De volledige vorm volgt met de kaart-taken. */
export interface PolicyKort {
  iri?: string;
  title?: string;
  isRequest?: boolean;
}

export interface Model {
  counts: {
    datasets: number; offers: number; agreements: number; sets: number;
    artifacts: number; bundles: number; versionContainers: number;
  };
  sets: PolicyKort[];
  offers: PolicyKort[];
  agreements: PolicyKort[];
  [sleutel: string]: unknown;
}

/** De RDF-graaf van één lading (een N3.Store). Ondoorzichtig voor de UI: alleen
 *  de modellaag leest hem; de app geeft hem terug aan `buildModel`. */
export type Graaf = object;

/** De navigatieboom (buildNav). Vorm volgt in de taak die de zijnav bouwt. */
export type Nav = unknown;

export interface ModelResultaat {
  model: Model;
  nav?: Nav;
  scopedNav?: Nav;
  /** Alleen op het synchrone pad: de worker stuurt de graaf apart (onStore). */
  store?: Graaf;
  errors?: Fout[];
  quadCount?: number;
}

/** Wat de worker ná het model terugstuurt: de graaf als termtabel + quadtabel. */
export type GraafLading = unknown;

export interface WorkerOpties {
  setScope?: string | null;
  lang?: string;
  onProgress?: (p: { phase: string; index?: number; total?: number; name?: string }) => void;
  onStore?: (lading: GraafLading | null) => void;
}

// De derde parameter (lang) is de expliciete taalkeuze; zonder hem geldt de
// actieve taal van de modellaag.
export const t = tJs as unknown as
  (key: string, vars?: Record<string, unknown>, lang?: string) => string;

export const detectFormat = detectFormatJs as unknown as
  (name: string, content: string) => string;

/** Bron-autodetectie voor één ?src=-waarde: bestand, endpoint of onbruikbaar.
 *  De databronnen komen mét inhoud terug — detectSource heeft er toch al een
 *  GET voor gedaan, en een tweede ophaling zou elke bron dubbel halen. */
export type BronDetectie =
  | { kind: 'sparql'; url: string }
  | { kind: 'data'; url: string; content: string; format: string }
  | { kind: 'error'; url: string; code: 'unreachable' | 'unsupported' | 'schema'; message: string };

export const detectSource = detectSourceJs as unknown as
  (url: string, fetchImpl?: typeof fetch) => Promise<BronDetectie>;

export const loadSources = loadSourcesJs as unknown as
  (sources: Bron[]) => ModelResultaat;

export const loadSourcesInWorker = loadSourcesInWorkerJs as unknown as
  (sources: Bron[], opties?: WorkerOpties) => Promise<ModelResultaat>;

/** Draagt deze knoop een eigen naam-literal (rdfs:label / skos:prefLabel /
 *  dct:title)? De vraag van de labelhaler in stores/corpus.ts: `labelFor` levert
 *  altijd iets (de localName is zijn terugval) en kan hem dus niet beantwoorden. */
export const hasOwnLabel = hasOwnLabelJs as unknown as
  (store: Graaf, term: string) => boolean;

export const stubOnlyContainers = stubOnlyContainersJs as unknown as
  (model: Model, kind: string) => unknown[];

// --- Hergebruik van de graaf (taalwissel, ?set=-wissel) ----------------------
// De oude viewer bouwt bij een taalwissel het MODEL opnieuw uit de bewaarde
// graaf (switchLang: `state.model = buildModel(state.store)`) — geen fetch en
// geen her-parse. Daarvoor moet de hoofddraad een gevulde store hebben; die
// komt op het worker-pad via de graaf-overdracht (`onStore` + hydrateInto).

export const createStore = createStoreJs as unknown as () => Graaf;

export const hydrateInto = hydrateIntoJs as unknown as
  (store: Graaf, lading: GraafLading) => Promise<Graaf>;

/** Eén quad zoals de graaf hem draagt. Ondoorzichtig op de termen na: de
 *  bewerklaag geeft ze door aan de modellaag, hij leest ze niet zelf. */
export interface Quad { subject: Term; predicate: Term; object: Term; graph?: Term }

/** Wat één bewerking aan de graaf veranderde — de vorm die de bewerkstore
 *  meldt en die bron-sync, het mutatielog en de gerichte invalidatie alle drie
 *  lezen. */
export interface Delta { added: Quad[]; removed: Quad[] }

/** `opties` maakt er een DEELHERBOUW van: policies die niet in `alleen` staan
 *  komen ongewijzigd uit `hergebruik` terug. Zie parse.js voor de belofte (het
 *  resultaat is gelijk aan een volle herbouw) en corpus.ts voor de terugval. */
export const buildModel = buildModelJs as unknown as
  (store: Graaf, opties?: { hergebruik?: Model | null; alleen?: Set<string> | null }) => Model;

/** Welke kaartmodellen kan deze delta geraakt hebben? `policies === null` = niet
 *  toe te wijzen; de aanroeper herbouwt dan volledig, en `reden` zegt of dat
 *  kwam doordat de mutatie buiten de kaartlaag viel of doordat de wandeling door
 *  haar knopenbudget zakte — twee heel verschillende diagnoses. */
export interface Toewijzing {
  policies: string[] | null;
  reden: '' | 'buiten-kaartlaag' | 'budget';
}

export const geraaktePolicies = geraaktePoliciesJs as unknown as
  (store: Graaf, delta: Delta, policyIris: Set<string> | Iterable<string>,
    opties?: { maxKnopen?: number }) => Toewijzing;

export const buildNav = buildNavJs as unknown as (model: Model) => Nav;

export const scopeNavToSet = scopeNavToSetJs as unknown as
  (nav: Nav, store: Graaf, setScope: string) => { nav: Nav } | null;

// ?policy= snoeit de boom tot het PAD naar die ene policy (en houdt wat eronder
// hangt). Anders dan scopeNavToSet heeft hij de graaf NIET nodig — hij loopt
// alleen de nav af — en anders dan die scoping doet de worker hem niet: die
// krijgt alleen setScope mee. `null` = de IRI zit niet in deze boom.
export const scopeNavToPolicy = scopeNavToPolicyJs as unknown as
  (nav: Nav, iri: string) => { nav: Nav; node: unknown } | null;

// --- De VERKENNER: één knoop, twee richtingen (taak 8a) ----------------------
// De verkenner leest de graaf rechtstreeks: één knoop met zijn literals en de
// twee verwijzingsrichtingen. Dezelfde functies die viewer-bevroren/assets/
// verken-view.js gebruikt; alleen hier staan hun vormen getypeerd.

/** Een term zoals de graaf hem draagt. Ondoorzichtig: de UI geeft hem terug. */
export type Term = { termType?: string; value?: string; id?: string };

/** Het predicaat van een verwijzing of waarde, met zijn leesbare naam. */
export interface PredicaatKop {
  iri: string;
  curie: string;
  label: string | null;
  desc: string | null;
}

/** Eén verwijzing (in- of uitgaand). `iri` is null bij een blanke knoop: die
 *  heeft buiten dit document geen adres en is dus geen link. */
export interface Verwijzing {
  term: Term;
  iri: string | null;
  curie: string | null;
  label: string | null;
  desc: string | null;
  predicate: PredicaatKop;
}

/** Eén literal van de knoop: wat hij over zichzelf zegt. */
export interface Waarde {
  value: string;
  lang: string | null;
  datatype: string | null;
  predicate: PredicaatKop;
}

/** De kop van een knoop: label, curie en typen. */
export interface KnoopKop {
  term: Term;
  iri: string | null;
  curie: string | null;
  label: string | null;
  desc: string | null;
  types: string[];
}

