// DE GRAAF-OVERDRACHT: de worker serialiseert, de hoofddraad hermonteert.
//
// Twee helften van één contract, en daarom in één module. De worker
// (`model-worker.js`) parst en stuurt de graaf als termtabel (één string +
// offsets, goedkope clone) plus een Uint32Array-quadtabel (transferable); de
// hoofddraad bouwt daaruit zijn eigen N3.Store (`model-client.js` re-exporteert
// `hydrateInto` hiervandaan). Stonden de twee helften los, dan is de ene te
// wijzigen zonder de andere — en juist hun SAMENHANG draagt de volgorde van de
// graaf.
//
// DE EIGENSCHAP: DE OVERDRACHT BEWAART DE VOLGORDE.
//
// N3 nummert elke term bij eerste vermelding (`N3EntityIndex._termToNewNumericId`)
// en indexeert quads onder die NUMMERS. Die indexen zijn objecten met
// integer-achtige sleutels, en JavaScript loopt zulke sleutels OPLOPEND af,
// ongeacht invoegvolgorde. De iteratievolgorde van een store — en daarmee de
// volgorde van élke `getQuads`, van de verwijzingenlijst in de verkenner tot de
// index-rijen — ligt dus volledig vast in de nummertoekenning.
//
// Deelt de hermontage die nummers opnieuw uit in een andere volgorde, dan
// itereert de hermonteerde store anders dan de geparste. Precies dat gebeurde:
// de termtabel werd gevuld in de volgorde waarin de termen in de QUADTABEL
// voorkwamen — de iteratievolgorde van de parse-store, niet de nummervolgorde
// ervan. Gemeten op het domeincorpus: 2.664 van de 5.394 quads kwamen er in een
// andere volgorde uit, en in de verkenner stonden 70 van de 211 verwijzingen
// naar `…/odrl-gegevensdeling/profiel` op een andere plek dan in de bevroren
// viewer (bevinding V5 van de dt4-verkennerdoorloop). Zichtbaar werd het pas in
// de nieuwe app omdat de bevroren viewer alleen BOVEN 1,5 MB naar de worker
// gaat en alle corpora daaronder zitten — dezelfde tweedeling als bij bevinding
// I-1 (het labelregister in de worker).
//
// Het herstel zit in twee helften die alleen SAMEN werken:
//   1. `serializeStore` draagt de termen over in de NUMMERVOLGORDE van de
//      bronstore;
//   2. `hydrateInto` deelt de nummers vooraf uit, in overdrachtsvolgorde.
// De nieuwe nummering is dan een MONOTONE hernummering van de oude (entiteiten
// zonder quad vallen weg, de rest houdt zijn onderlinge rangorde), en een
// monotone hernummering laat elke oplopende iteratie ongemoeid. Elk van de twee
// helften alléén herstelt niets: beide staan dan nog op 70 van de 211 (gemeten,
// de probe bij bevinding V5).
import * as N3 from 'n3';

const { Store, termFromId } = N3;

/** Een lege hoofddraad-store om in te hermonteren. */
export function createStore() { return new Store(); }

/** De graaf inpakken voor de worker-grens: termtabel + quadtabel.
 *
 *  De termtabel staat in de NUMMERVOLGORDE van `store` (zie de kop). Kent de
 *  store zijn entiteitsindex niet — een andere n3-versie, een andere
 *  store-implementatie — dan valt de volgorde terug op eerste vermelding in de
 *  quadtabel: de overdracht blijft dan correct, alleen de volgordegarantie
 *  vervalt. Dát is wat `test/graafoverdracht.test.mjs` bewaakt; hij staat rood
 *  zodra die terugval de werkzame weg wordt. */
export function serializeStore(store) {
  const quads = store.getQuads(null, null, null, null);
  const termIds = [];
  const index = new Map();
  const voegToe = (id) => {
    if (!index.has(id)) { index.set(id, termIds.length); termIds.push(id); }
  };
  const entiteiten = store._entityIndex && store._entityIndex._entities;
  if (entiteiten) {
    const gebruikt = new Set();
    for (const q of quads) {
      gebruikt.add(q.subject.id); gebruikt.add(q.predicate.id);
      gebruikt.add(q.object.id); gebruikt.add(q.graph.id);
    }
    // Oplopend op nummer. Object.keys geeft integer-achtige sleutels al
    // oplopend terug; de sort maakt die afhankelijkheid expliciet.
    for (const nr of Object.keys(entiteiten).map(Number).sort((a, b) => a - b)) {
      if (gebruikt.has(entiteiten[nr])) voegToe(entiteiten[nr]);
    }
  }
  const quadTable = new Uint32Array(quads.length * 4);
  let j = 0;
  for (const q of quads) {
    // Wat de entiteitsindex niet kende (of: de hele tabel, als er geen index
    // is) komt hier alsnog binnen, op eerste vermelding.
    voegToe(q.subject.id); voegToe(q.predicate.id);
    voegToe(q.object.id); voegToe(q.graph.id);
    quadTable[j++] = index.get(q.subject.id);
    quadTable[j++] = index.get(q.predicate.id);
    quadTable[j++] = index.get(q.object.id);
    quadTable[j++] = index.get(q.graph.id);
  }
  const termOffsets = new Uint32Array(termIds.length + 1);
  for (let i = 0; i < termIds.length; i++) {
    termOffsets[i + 1] = termOffsets[i] + termIds[i].length;
  }
  const termText = termIds.join('');
  return { termText, termOffsets, quadTable };
}

/** Vul een (lege) N3.Store uit de graaf-overdracht, in stukjes
 *  (setTimeout-slices) zodat de hoofddraad responsief blijft; resolvet als de
 *  store vol is. De termtabel komt als één string + offsets binnen (goedkope
 *  clone); de losse term-id's worden hier uitgesneden.
 *
 *  De NUMMERS worden VOORAF uitgedeeld, in overdrachtsvolgorde — de tweede
 *  helft van de volgordegarantie (zie de kop). Dat gebeurt in één keer en niet
 *  chunk voor chunk: het moet áf zijn vóór de eerste `addQuad`, anders deelt
 *  die de nummers zelf al uit in de volgorde van de quadtabel. De luie
 *  term-opbouw vervalt daarmee, maar dat kost niets: elke term in de tabel
 *  wordt toch door minstens één quad gebruikt. GEMETEN op het domeincorpus
 *  (5.394 quads, 3.430 termen, mediaan van vijf ronden, node in de container):
 *  hermonteren 71,9 -> 75,1 ms op de hoofddraad, serialiseren 16,6 -> 23,1 ms
 *  in de worker, en de overdracht zelf even groot (203.387 tekens termtekst,
 *  dezelfde quadtabel) — het is een andere VOLGORDE, geen extra last. */
export function hydrateInto(store, { termText, termOffsets, quadTable }, { chunkSize = 25000, onProgress = null } = {}) {
  const aantalTermen = termOffsets.length - 1;
  const terms = new Array(aantalTermen);
  for (let ix = 0; ix < aantalTermen; ix++) {
    terms[ix] = termFromId(termText.substring(termOffsets[ix], termOffsets[ix + 1]));
  }
  const entiteitsIndex = store._entityIndex;
  if (entiteitsIndex && entiteitsIndex._termToNewNumericId) {
    for (const t of terms) entiteitsIndex._termToNewNumericId(t);
  }
  const term = (ix) => terms[ix];
  const totalQuads = quadTable.length / 4;
  return new Promise((resolve) => {
    let i = 0;
    const step = () => {
      const end = Math.min(totalQuads, i + chunkSize);
      for (; i < end; i++) {
        store.addQuad(term(quadTable[i * 4]), term(quadTable[i * 4 + 1]),
          term(quadTable[i * 4 + 2]), term(quadTable[i * 4 + 3]));
      }
      if (onProgress) onProgress(i, totalQuads);
      if (i < totalQuads) setTimeout(step, 0);
      else resolve(store);
    };
    step();
  });
}
